<template>
  <div class="clusters-layout-frame">
  <div class="kvm-page clusters-page">
    <header class="clusters-header">
      <div><span class="eyebrow">SUSE LINUX ENTERPRISE HIGH AVAILABILITY</span><h1>{{ t('clusters.title') }}</h1><p>{{ t('clusters.subtitle') }}</p></div>
      <div class="cluster-heading-actions"><button class="btn role-primary" @click="openManagedKvmClusters">{{ t('clusters.managedKvmClusters') }}</button><button class="btn role-secondary" :disabled="loading || refreshingStale" @click="load">{{ loading || refreshingStale ? t('clusters.refreshing') : t('clusters.refresh') }}</button></div>
    </header>

    <div v-if="error" class="banner error" role="alert">{{ error }}</div>
    <div v-if="loading && !loaded" class="loading">{{ t('clusters.loading') }}</div>
    <template v-else>
      <div class="cluster-stats">
        <article><span>{{ t('clusters.registeredHosts') }}</span><strong>{{ hosts.length }}</strong></article>
        <article><span>{{ t('clusters.haEnabledHosts') }}</span><strong>{{ haEnabledCount }}</strong><small>{{ t('clusters.haEnabledHostsHelp') }}</small></article>
        <article><span>{{ t('clusters.clusterHosts') }}</span><strong>{{ clusterHostCount }}</strong><small>{{ t('clusters.clusterHostsHelp') }}</small></article>
      </div>

      <nav class="cluster-nav" role="tablist" :aria-label="t('clusters.navigation')">
        <button v-for="(section, index) in sections" :id="`cluster-tab-${section}`" :key="section" class="cluster-nav-item" role="tab" :tabindex="activeSection === section ? 0 : -1" :aria-selected="activeSection === section" :aria-controls="activeSection === section ? `cluster-panel-${section}` : undefined" @click="selectSection(section)" @keydown="onNavigationKeydown($event, index)">
          <span class="nav-icon" aria-hidden="true">{{ sectionIcon(section) }}</span>{{ t(`clusters.section_${section}`) }}
          <span v-if="section === 'nodes'" class="nav-count">{{ hosts.length }}</span>
        </button>
      </nav>
      <label class="cluster-mobile-picker"><span>{{ t('clusters.navigation') }}</span><select :value="activeSection" @change="selectSectionFromPicker"><option v-for="section in sections" :key="section" :value="section">{{ t(`clusters.section_${section}`) }}</option></select></label>

      <section v-if="activeSection === 'clusters'" id="cluster-panel-clusters" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t('clusters.inventoryTitle') }}</h2><p>{{ t('clusters.inventoryDescription') }}</p></div><button class="btn role-primary" @click="activeSection = 'plan'">{{ t('clusters.startPlanning') }}</button></div>
        <section class="host-ha-tools" aria-labelledby="host-ha-tools-title">
          <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.readiness') }}</span><h2 id="host-ha-tools-title">{{ t('clusters.haToolsPanelTitle') }}</h2><p>{{ t('clusters.haToolsPanelHelp') }}</p></div><div class="cluster-heading-actions"><button class="btn role-primary btn-sm" :disabled="!canManageCluster || !haToolsEligibleHosts.length || haToolsBatchLoading || haToolBusyHostIds.length > 0" :title="!canManageCluster ? t('clusters.operatorRoleRequired') : !haToolsEligibleHosts.length ? t('clusters.haToolsNoEligibleHelp') : ''" @click="installHaToolsForEligibleHosts">{{ haToolsBatchLoading ? t('clusters.haToolsBatchInstalling') : haToolsEligibleHosts.length ? t('clusters.enableHaToolsBatch', { count: haToolsEligibleHosts.length }) : t('clusters.haToolsNoEligible') }}</button><button class="btn role-link btn-sm" @click="activeSection = 'overview'">{{ t('clusters.viewHostReadiness') }}</button></div></div>
          <div class="inline-callout info readiness-sequence"><strong>{{ t('clusters.readinessSequenceTitle') }}</strong><ol><li>{{ t('clusters.readinessAddon') }}</li><li>{{ t('clusters.readinessTools') }}</li><li>{{ t('clusters.readinessConfigure') }}</li><li>{{ t('clusters.readinessVerify') }}</li></ol></div>
          <div v-if="!hosts.length" class="inline-callout info"><strong>{{ t('clusters.noHosts') }}</strong><p>{{ t('clusters.noHostsHelp') }}</p></div>
          <div v-else class="table-wrap"><table class="table"><thead><tr><th>{{ t('clusters.host') }}</th><th>{{ t('clusters.haAddon') }}</th><th>{{ t('clusters.clusterStack') }}</th><th>{{ t('clusters.operations') }}</th></tr></thead><tbody>
            <tr v-for="host in hosts" :key="`ha-tools-${host.id}`">
              <td><strong>{{ host.hostname || host.name }}</strong><small>{{ host.address }}:{{ host.port }}</small></td>
              <td><span class="state" :class="haClass(host)"><i></i>{{ haLabel(host) }}</span><small v-if="host.ha?.ha_product">{{ host.ha.ha_product }}</small><small v-else-if="host.ha?.inspection_error">{{ host.ha.inspection_error }}</small></td>
              <td><div class="stack-status"><span :class="serviceClass(host,'pacemaker')">{{ t('clusters.pacemaker') }}: {{ serviceLabel(host,'pacemaker') }}</span><span :class="serviceClass(host,'corosync')">{{ t('clusters.corosync') }}: {{ serviceLabel(host,'corosync') }}</span><span :class="serviceClass(host,'hawk')">{{ t('clusters.hawk') }}: {{ serviceLabel(host,'hawk') }}</span></div></td>
              <td class="action-cell"><div class="cell-action-controls"><span v-if="host.ha?.ha_active && haToolsInstalled(host)" class="state ready ha-tools-state"><i></i>{{ t('clusters.haToolsInstalled') }}</span><button v-else-if="host.ha?.ha_active" class="btn role-primary btn-sm" :disabled="!canManageCluster || haToolBusyHostIds.includes(host.id)" :title="!canManageCluster ? t('clusters.operatorRoleRequired') : ''" @click="installHaTools(host)">{{ haToolBusyHostIds.includes(host.id) ? t('clusters.haToolsInstalling') : t('clusters.enableHaTools') }}</button><span v-else-if="host.ha?.ha_available">{{ t('clusters.activateHaAddonFirst') }}</span><span v-else>{{ t('clusters.haUnavailable') }}</span><div v-if="haToolResults[host.id]" class="ha-tool-result" :class="haToolResults[host.id].status" role="status" aria-live="polite"><span>{{ haToolResults[host.id].message || haToolResults[host.id].error || operationStatusText(haToolResults[host.id].status) }}</span><small v-if="haToolResults[host.id].status === 'installed'">{{ t('clusters.serviceActivationGuide') }}</small></div></div></td>
            </tr>
          </tbody></table></div>
          <div v-if="!canManageCluster" class="inline-callout info"><strong>{{ t('clusters.readOnly') }}</strong><p>{{ t('clusters.operatorRoleRequired') }}</p></div>
        </section>
        <div v-if="clusterHostCount === 0" class="empty-state"><div class="preview-icon" aria-hidden="true">◇</div><h3>{{ t('clusters.noClusters') }}</h3><p>{{ t('clusters.noClustersHelp') }}</p><button class="btn role-primary" @click="activeSection = 'plan'">{{ t('clusters.planFirstCluster') }}</button></div>
        <template v-else>
          <div class="cluster-source-list"><article v-for="host in clusterHosts" :key="host.ha?.cluster_identity || host.id" class="cluster-source-card"><div><strong>{{ host.ha?.cluster_name || host.hostname || host.name }}</strong><small>{{ t('clusters.reportedBy', { host: host.hostname || host.name }) }}</small><small v-if="host.ha?.cluster_members?.length">{{ t('clusters.confirmedMembers', { members: host.ha.cluster_members.join(', ') }) }}</small><span class="state ready"><i></i>{{ t('clusters.clusterDetected') }}</span></div><button class="btn role-primary btn-sm" :disabled="clusterStatusLoading" @click="openCluster(host)">{{ t('clusters.openCluster') }}</button></article></div>
          <div v-if="clusterStatusLoading" class="loading compact">{{ t('clusters.clusterLoading') }}</div>
          <div v-if="clusterStatusError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.clusterStatusError') }}</strong><p>{{ clusterStatusError }}</p></div>
          <template v-if="clusterStatus">
            <div class="cluster-detail-heading"><div><span class="eyebrow">{{ t('clusters.liveStatus') }}</span><h3>{{ clusterStatus.cluster_name || t('clusters.unnamedCluster') }}</h3><small>{{ t('clusters.statusSource', { host: clusterStatus.source_host_name }) }} · {{ dateLabel(clusterStatus.checked_at) }}</small></div><div class="cluster-heading-actions"><a v-if="clusterDiagnostics?.hawk_url" class="btn role-secondary btn-sm" :href="clusterDiagnostics.hawk_url" target="_blank" rel="noopener noreferrer">{{ t('clusters.openHawk') }}</a><button class="btn role-secondary btn-sm" :disabled="clusterStatusLoading" @click="fetchClusterStatus">{{ t('clusters.refresh') }}</button></div></div>
            <div class="cluster-detail-stats"><article><small>{{ t('clusters.nodes') }}</small><strong>{{ clusterStatus.online_count || 0 }} / {{ clusterStatus.node_count || 0 }}</strong><span>{{ t('clusters.onlineNodes') }}</span></article><article><small>{{ t('clusters.resources') }}</small><strong>{{ clusterStatus.resource_count || 0 }}</strong><span>{{ t('clusters.managedResources') }}</span></article><article><small>{{ t('clusters.quorum') }}</small><strong :class="clusterStatus.quorum?.quorate ? 'healthy-text' : 'warning-text'">{{ clusterStatus.quorum?.quorate ? t('clusters.quorate') : clusterStatus.quorum?.available ? t('clusters.notQuorate') : t('clusters.quorumUnknown') }}</strong><span>{{ quorumSummary }}</span></article><article><small>{{ t('clusters.fencing') }}</small><strong :class="clusterStatus.fencing?.configured ? 'healthy-text' : 'warning-text'">{{ clusterStatus.fencing?.configured ? t('clusters.fencingConfigured') : clusterStatus.fencing?.available ? t('clusters.fencingNotConfigured') : t('clusters.fencingUnknown') }}</strong><span>{{ fencingSummary }}</span></article></div>
            <div class="cluster-shortcuts"><button class="btn role-link" @click="activeSection = 'nodes'">{{ t('clusters.manageNodes') }}</button><button class="btn role-link" @click="activeSection = 'resources'">{{ t('clusters.manageResources') }}</button><button class="btn role-link" @click="activeSection = 'fencing'">{{ t('clusters.reviewQuorumFencing') }}</button></div>
          </template>
        </template>
        <p class="safety-note">{{ t('clusters.inventorySeparation') }}</p>
      </section>

      <section v-else-if="activeSection === 'nodes' || activeSection === 'resources'" :id="`cluster-panel-${activeSection}`" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t(`clusters.section_${activeSection}`) }}</h2><p>{{ t(`clusters.area_${activeSection}_description`) }}</p></div><div class="cluster-heading-actions"><button v-if="activeSection === 'resources' && canManageCluster && clusterStatus" class="btn role-primary" @click="openCreateResource">{{ t('clusters.createResource') }}</button><button class="btn role-secondary" :disabled="clusterStatusLoading || !activeClusterHostId" @click="fetchClusterStatus">{{ t('clusters.refresh') }}</button></div></div>
        <div v-if="!clusterStatus && !clusterStatusLoading" class="inline-callout info"><strong>{{ t('clusters.noLiveCluster') }}</strong><p>{{ clusterStatusError || t('clusters.noLiveClusterHelp') }}</p><button class="btn role-link" @click="activeSection = 'clusters'">{{ t('clusters.viewClusters') }}</button></div>
        <template v-else-if="clusterStatus">
          <div v-if="activeSection === 'nodes'" class="table-wrap"><table class="table"><thead><tr><th>{{ t('clusters.node') }}</th><th>{{ t('clusters.nodeStatus') }}</th><th>{{ t('clusters.standby') }}</th><th>{{ t('clusters.maintenance') }}</th><th>{{ t('clusters.operations') }}</th></tr></thead><tbody><tr v-for="node in clusterStatus.nodes" :key="node.id || node.name"><td><strong>{{ node.name }}</strong><small>{{ t('clusters.nodeId') }}: {{ node.id || '—' }}</small></td><td><span class="state" :class="node.online && !node.unclean ? 'ready' : 'unreachable'"><i></i>{{ node.online ? (node.unclean ? t('clusters.unclean') : t('clusters.online')) : t('clusters.offline') }}</span><small v-if="node.pending">{{ node.pending }}</small></td><td>{{ node.standby ? t('clusters.enabledState') : t('clusters.disabledState') }}</td><td>{{ node.maintenance ? t('clusters.enabledState') : t('clusters.disabledState') }}</td><td class="action-cell"><div class="cell-action-controls"><button v-if="!node.standby" class="btn role-secondary btn-sm" @click="requestClusterAction('node_standby', node.name)">{{ t('clusters.standbyNode') }}</button><button v-else class="btn role-secondary btn-sm" @click="requestClusterAction('node_online', node.name)">{{ t('clusters.bringOnline') }}</button><button v-if="!node.maintenance" class="btn role-secondary btn-sm" @click="requestClusterAction('node_maintenance', node.name)">{{ t('clusters.enterMaintenance') }}</button><button v-else class="btn role-secondary btn-sm" @click="requestClusterAction('node_ready', node.name)">{{ t('clusters.leaveMaintenance') }}</button></div></td></tr></tbody></table></div>
          <template v-else>
            <form v-if="resourceEditor?.mode === 'create'" class="resource-editor" @submit.prevent="prepareResourceCreate">
              <div class="editor-heading"><div><span class="eyebrow">{{ t('clusters.resourceConfiguration') }}</span><h3>{{ t('clusters.createPrimitiveTitle') }}</h3><p>{{ t('clusters.createPrimitiveHelp') }}</p></div><button type="button" class="btn role-link btn-sm" @click="resourceEditor = null">{{ t('clusters.cancelAction') }}</button></div>
              <div class="resource-form-grid"><label>{{ t('clusters.resourceId') }}<input v-model.trim="resourceEditor.resource_id" required maxlength="128" pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" autocomplete="off" /></label><label>{{ t('clusters.resourceAgent') }}<select v-model="resourceEditor.agent" required @change="loadResourceAgentInfo"><option value="">{{ t('clusters.selectResourceAgent') }}</option><option v-for="agent in resourceAgents" :key="agent" :value="agent">{{ agent }}</option></select></label><label class="field-wide">{{ t('clusters.resourceParameters') }}<textarea v-model="resourceEditor.parametersText" rows="4" :placeholder="t('clusters.resourceParametersPlaceholder')" spellcheck="false"></textarea><small>{{ t('clusters.resourceParametersHelp') }}</small></label></div>
              <article v-if="resourceAgentInfo" class="diagnostic-card"><h4>{{ t('clusters.resourceAgentGuide', { agent: resourceEditor.agent }) }}</h4><pre>{{ resourceAgentInfo }}</pre></article>
              <div v-if="resourceAgentsError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.resourceAgentsUnavailable') }}</strong><p>{{ resourceAgentsError }}</p></div>
              <div class="row-actions"><button type="button" class="btn role-secondary" @click="resourceEditor = null">{{ t('clusters.cancelAction') }}</button><button class="btn role-primary" :disabled="resourceMutationBusy || !resourceEditor.agent || !resourceEditor.resource_id">{{ t('clusters.reviewResourceCreate') }}</button></div>
            </form>
            <form v-else-if="resourceEditor?.mode === 'edit'" class="resource-editor" @submit.prevent="prepareResourceEdit">
              <div class="editor-heading"><div><span class="eyebrow">{{ t('clusters.resourceConfiguration') }}</span><h3>{{ t('clusters.editResourceTitle', { id: resourceEditor.resource_id }) }}</h3><p>{{ t('clusters.editResourceHelp') }}</p></div><button type="button" class="btn role-link btn-sm" @click="resourceEditor = null">{{ t('clusters.cancelAction') }}</button></div>
              <div class="resource-form-grid"><label>{{ t('clusters.attributeType') }}<select v-model="resourceEditor.attributeType"><option value="param">{{ t('clusters.resourceParameter') }}</option><option value="meta">{{ t('clusters.resourceMeta') }}</option></select></label><label>{{ t('clusters.attributeAction') }}<select v-model="resourceEditor.attributeAction"><option value="set">{{ t('clusters.setAttribute') }}</option><option value="delete">{{ t('clusters.deleteAttribute') }}</option></select></label><label>{{ t('clusters.attributeName') }}<input v-model.trim="resourceEditor.key" required maxlength="64" pattern="[A-Za-z_][A-Za-z0-9_.-]*" autocomplete="off" /></label><label v-if="resourceEditor.attributeAction === 'set'">{{ t('clusters.attributeValue') }}<input v-model="resourceEditor.value" required maxlength="2048" autocomplete="off" /></label></div>
              <div class="row-actions"><button type="button" class="btn role-secondary" @click="resourceEditor = null">{{ t('clusters.cancelAction') }}</button><button class="btn role-primary" :disabled="resourceMutationBusy || !resourceEditor.key">{{ t('clusters.reviewResourceEdit') }}</button></div>
            </form>
            <div class="table-wrap"><table class="table"><thead><tr><th>{{ t('clusters.resource') }}</th><th>{{ t('clusters.resourceType') }}</th><th>{{ t('clusters.resourceStatus') }}</th><th>{{ t('clusters.location') }}</th><th>{{ t('clusters.operations') }}</th></tr></thead><tbody><tr v-for="resource in clusterStatus.resources" :key="resource.id"><td><strong>{{ resource.id }}</strong></td><td>{{ resource.agent || '—' }}</td><td><span class="state" :class="resource.failed ? 'unreachable' : resource.active ? 'ready' : 'warning-state'"><i></i>{{ resource.failed ? t('clusters.failed') : resource.active ? (resource.role || t('clusters.running')) : t('clusters.stopped') }}</span><small v-if="!resource.managed">{{ t('clusters.unmanaged') }}</small></td><td>{{ resource.nodes?.join(', ') || '—' }}</td><td class="action-cell"><div class="cell-action-controls"><button v-if="resource.active" class="btn role-secondary btn-sm" @click="requestClusterAction('resource_stop', resource.id)">{{ t('clusters.stopResource') }}</button><button v-else class="btn role-secondary btn-sm" @click="requestClusterAction('resource_start', resource.id)">{{ t('clusters.startResource') }}</button><button v-if="resource.failed" class="btn role-secondary btn-sm" @click="requestClusterAction('resource_cleanup', resource.id)">{{ t('clusters.cleanupResource') }}</button><button v-if="canManageCluster && resource.managed" class="btn role-link btn-sm" @click="openResourceEditor(resource)">{{ t('clusters.editResource') }}</button><button v-if="canManageCluster && resource.managed" class="btn role-link btn-sm danger-text" @click="prepareResourceDelete(resource)">{{ t('clusters.deleteResource') }}</button></div></td></tr><tr v-if="!clusterStatus.resources?.length"><td colspan="5" class="empty-row">{{ t('clusters.noResources') }}</td></tr></tbody></table></div>
          </template>
        </template>
        <div v-if="!canManageCluster && clusterStatus" class="inline-callout info"><strong>{{ t('clusters.readOnly') }}</strong><p>{{ t('clusters.operatorRoleRequired') }}</p></div>
        <div v-if="pendingClusterAction" class="inline-callout warning action-review"><strong>{{ t('clusters.confirmActionTitle') }}</strong><p>{{ actionReviewText }}</p><small>{{ t('clusters.actionRiskNote') }}</small><div><button class="btn role-primary btn-sm" :disabled="clusterActionBusy" @click="runClusterAction">{{ clusterActionBusy ? t('clusters.actionRunning') : t('clusters.confirmAction') }}</button><button class="btn role-secondary btn-sm" :disabled="clusterActionBusy" @click="pendingClusterAction = null">{{ t('clusters.cancelAction') }}</button></div></div>
        <div v-if="clusterActionError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.actionFailed') }}</strong><p>{{ clusterActionError }}</p></div><div v-if="clusterActionMessage" class="inline-callout success" role="status"><strong>{{ t('clusters.actionSucceeded') }}</strong><p>{{ clusterActionMessage }}</p></div>
        <div v-if="pendingResourceMutation" class="inline-callout warning action-review"><strong>{{ t('clusters.reviewResourceChangeTitle') }}</strong><p>{{ resourceMutationSummary }}</p><small>{{ t('clusters.resourceChangeSafety') }}</small><p v-if="resourceMutationError" role="alert">{{ resourceMutationError }}</p><div><button class="btn role-primary btn-sm" :disabled="resourceMutationBusy" @click="runResourceMutation">{{ resourceMutationBusy ? t('clusters.resourceChangeRunning') : t('clusters.confirmAction') }}</button><button class="btn role-secondary btn-sm" :disabled="resourceMutationBusy" @click="pendingResourceMutation = null">{{ t('clusters.cancelAction') }}</button></div></div>
        <div v-if="resourceMutationMessage" class="inline-callout success" role="status"><strong>{{ t('clusters.resourceChangeSucceeded') }}</strong><p>{{ resourceMutationMessage }}</p></div>
        <p class="safety-note">{{ t('clusters.nodeActionSafety') }}</p>
      </section>

      <section v-else-if="activeSection === 'fencing'" id="cluster-panel-fencing" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t('clusters.section_fencing') }}</h2><p>{{ t('clusters.fencingDetailDescription') }}</p></div><button class="btn role-secondary" :disabled="clusterStatusLoading || !activeClusterHostId" @click="fetchClusterStatus">{{ t('clusters.refresh') }}</button></div>
        <div v-if="clusterStatus" class="fencing-grid"><article><span class="state" :class="clusterStatus.quorum?.quorate ? 'ready' : 'warning-state'"><i></i>{{ clusterStatus.quorum?.quorate ? t('clusters.quorate') : clusterStatus.quorum?.available ? t('clusters.notQuorate') : t('clusters.quorumUnknown') }}</span><pre v-if="clusterStatus.quorum?.summary">{{ clusterStatus.quorum.summary }}</pre><p v-else>{{ t('clusters.quorumHelp') }}</p></article><article><span class="state" :class="clusterStatus.fencing?.configured ? 'ready' : 'warning-state'"><i></i>{{ clusterStatus.fencing?.configured ? t('clusters.fencingConfigured') : clusterStatus.fencing?.available ? t('clusters.fencingNotConfigured') : t('clusters.fencingUnknown') }}</span><pre v-if="clusterStatus.fencing?.summary">{{ clusterStatus.fencing.summary }}</pre><p v-else>{{ t('clusters.fencingHelp') }}</p></article></div><div v-else class="inline-callout info"><strong>{{ t('clusters.noLiveCluster') }}</strong><p>{{ clusterStatusError || t('clusters.noLiveClusterHelp') }}</p></div>
        <article v-if="clusterDiagnostics" class="diagnostic-card"><h3>{{ t('clusters.corosyncLinks') }}</h3><pre v-if="clusterDiagnostics.corosync?.available">{{ clusterDiagnostics.corosync.summary }}</pre><p v-else>{{ clusterDiagnostics.corosync?.error || t('clusters.diagnosticsUnavailable') }}</p></article>
        <div class="inline-callout warning"><strong>{{ t('clusters.twoNodeTitle') }}</strong><p>{{ t('clusters.fencingBestPractice') }}</p></div>
      </section>

      <section v-else-if="activeSection === 'constraints'" id="cluster-panel-constraints" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t('clusters.section_constraints') }}</h2><p>{{ t('clusters.area_constraints_description') }}</p></div><div class="cluster-heading-actions"><button v-if="canManageCluster && clusterStatus" class="btn role-primary" @click="openConstraintEditor('create_location')">{{ t('clusters.addConstraint') }}</button><button class="btn role-secondary" :disabled="diagnosticsLoading || !activeClusterHostId" @click="fetchClusterDiagnostics">{{ diagnosticsLoading ? t('clusters.diagnosticsLoading') : t('clusters.refresh') }}</button></div></div>
        <div v-if="!activeClusterHostId" class="inline-callout info"><strong>{{ t('clusters.noLiveCluster') }}</strong><p>{{ t('clusters.selectClusterForDetails') }}</p><button class="btn role-link" @click="activeSection = 'clusters'">{{ t('clusters.viewClusters') }}</button></div>
        <div v-else-if="diagnosticsLoading" class="loading compact">{{ t('clusters.diagnosticsLoading') }}</div>
        <template v-else-if="clusterDiagnostics || clusterDiagnosticsError">
          <div v-if="clusterDiagnosticsError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.diagnosticsError') }}</strong><p>{{ clusterDiagnosticsError }}</p></div>
          <div v-if="constraintEditor" class="resource-editor"><div class="editor-heading"><div><span class="eyebrow">{{ t('clusters.constraintConfiguration') }}</span><h3>{{ t(`clusters.${constraintEditor.action}`) }}</h3><p>{{ t('clusters.constraintEditorHelp') }}</p></div><button type="button" class="btn role-link btn-sm" @click="constraintEditor = null">{{ t('clusters.cancelAction') }}</button></div><div class="resource-form-grid"><label>{{ t('clusters.constraintId') }}<input v-model.trim="constraintEditor.constraint_id" required maxlength="128" pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" autocomplete="off" /></label><label>{{ t('clusters.constraintType') }}<select :value="constraintEditor.action" @change="changeConstraintType($event)"><option value="create_location">{{ t('clusters.constraint_location') }}</option><option value="create_order">{{ t('clusters.constraint_ordering') }}</option><option value="create_colocation">{{ t('clusters.constraint_colocation') }}</option></select></label><label>{{ t('clusters.resource') }}<select v-model="constraintEditor.resource" required><option value="">{{ t('clusters.selectResource') }}</option><option v-for="resource in clusterStatus?.resources || []" :key="resource.id" :value="resource.id">{{ resource.id }}</option></select></label><label v-if="constraintEditor.action !== 'create_location'">{{ t('clusters.otherResource') }}<select v-model="constraintEditor.other_resource" required><option value="">{{ t('clusters.selectResource') }}</option><option v-for="resource in clusterStatus?.resources || []" :key="resource.id" :value="resource.id">{{ resource.id }}</option></select></label><label v-if="constraintEditor.action === 'create_location'">{{ t('clusters.clusterNode') }}<select v-model="constraintEditor.node" required><option value="">{{ t('clusters.selectNode') }}</option><option v-for="node in clusterStatus?.nodes || []" :key="node.id || node.name" :value="node.name">{{ node.name }}</option></select></label><label v-if="constraintEditor.action === 'create_location' || constraintEditor.action === 'create_colocation'">{{ t('clusters.constraintScore') }}<input v-model.trim="constraintEditor.score" required maxlength="16" placeholder="INFINITY, -INFINITY, 100" /></label><label v-if="constraintEditor.action === 'create_order'">{{ t('clusters.orderKind') }}<select v-model="constraintEditor.order_kind"><option value="Mandatory">Mandatory</option><option value="Optional">Optional</option><option value="Serialize">Serialize</option></select></label></div><div class="row-actions"><button type="button" class="btn role-secondary" @click="constraintEditor = null">{{ t('clusters.cancelAction') }}</button><button type="button" class="btn role-primary" :disabled="!constraintEditor.constraint_id || !constraintEditor.resource" @click="prepareConstraintMutation">{{ t('clusters.reviewConstraint') }}</button></div></div>
          <div v-if="constraintMutationError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.constraintMutationFailed') }}</strong><p>{{ constraintMutationError }}</p></div><div v-if="constraintMutationMessage" class="inline-callout success" role="status"><strong>{{ t('clusters.constraintMutationSucceeded') }}</strong><p>{{ constraintMutationMessage }}</p></div>
          <div v-if="pendingConstraintMutation" class="inline-callout warning action-review"><strong>{{ t('clusters.reviewConstraintTitle') }}</strong><p>{{ constraintMutationSummary }}</p><small>{{ t('clusters.constraintChangeSafety') }}</small><div><button class="btn role-primary btn-sm" :disabled="constraintMutationBusy" @click="runConstraintMutation">{{ constraintMutationBusy ? t('clusters.constraintChangeRunning') : t('clusters.confirmAction') }}</button><button class="btn role-secondary btn-sm" :disabled="constraintMutationBusy" @click="pendingConstraintMutation = null">{{ t('clusters.cancelAction') }}</button></div></div>
          <div class="constraint-groups"><article v-for="kind in ['location','ordering','colocation']" :key="kind" class="diagnostic-card"><h3>{{ t(`clusters.constraint_${kind}`) }}</h3><ul v-if="clusterDiagnostics.constraints?.[kind]?.items?.length"><li v-for="item in clusterDiagnostics.constraints[kind].items" :key="item"><span>{{ item }}</span><button v-if="canManageCluster" class="btn role-link btn-sm danger-text" :aria-label="t('clusters.deleteConstraint', { id: constraintId(item) })" @click="prepareConstraintDelete(item)">{{ t('clusters.deleteConstraintShort') }}</button></li></ul><p v-else>{{ clusterDiagnostics.constraints?.[kind]?.error || t('clusters.noConstraints') }}</p></article></div>
          <small class="data-stamp">{{ t('clusters.diagnosticsCheckedAt') }}: {{ dateLabel(clusterDiagnostics.checked_at) }}</small>
        </template>
      </section>

      <section v-else-if="activeSection === 'activity'" id="cluster-panel-activity" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t('clusters.section_activity') }}</h2><p>{{ t('clusters.area_activity_description') }}</p></div><button class="btn role-secondary" :disabled="diagnosticsLoading || !activeClusterHostId" @click="fetchClusterDiagnostics">{{ diagnosticsLoading ? t('clusters.diagnosticsLoading') : t('clusters.refresh') }}</button></div>
        <div v-if="!activeClusterHostId" class="inline-callout info"><strong>{{ t('clusters.noLiveCluster') }}</strong><p>{{ t('clusters.selectClusterForDetails') }}</p><button class="btn role-link" @click="activeSection = 'clusters'">{{ t('clusters.viewClusters') }}</button></div>
        <div v-else-if="diagnosticsLoading" class="loading compact">{{ t('clusters.diagnosticsLoading') }}</div>
        <template v-else-if="clusterDiagnostics || clusterDiagnosticsError"><div v-if="clusterDiagnosticsError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.diagnosticsError') }}</strong><p>{{ clusterDiagnosticsError }}</p></div><article v-if="clusterDiagnostics" class="diagnostic-card"><h3>{{ t('clusters.recentServiceEvents') }}</h3><pre v-if="clusterDiagnostics.activity?.available && clusterDiagnostics.activity.summary">{{ clusterDiagnostics.activity.summary }}</pre><p v-else>{{ clusterDiagnostics.activity?.error || t('clusters.noActivity') }}</p></article><small v-if="clusterDiagnostics" class="data-stamp">{{ t('clusters.diagnosticsWindow') }} · {{ dateLabel(clusterDiagnostics.checked_at) }}</small></template>
      </section>

      <section v-else-if="activeSection === 'overview'" id="cluster-panel-overview" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.readiness') }}</span><h2>{{ t('clusters.hostsTitle') }}</h2><p>{{ t('clusters.hostsDescription') }}</p></div><button class="btn role-primary" @click="goToHosts">{{ t('clusters.manageHosts') }}</button></div>
        <div v-if="!hosts.length" class="empty-state"><h3>{{ t('clusters.noHosts') }}</h3><p>{{ t('clusters.noHostsHelp') }}</p><button class="btn role-primary" @click="goToHosts">{{ t('clusters.addHost') }}</button></div>
        <div v-else class="table-wrap"><table class="table"><thead><tr><th>{{ t('clusters.host') }}</th><th>{{ t('clusters.hostState') }}</th><th>{{ t('clusters.haAddon') }}</th><th>{{ t('clusters.clusterStack') }}</th><th>{{ t('clusters.clusterState') }}</th><th>{{ t('clusters.resources') }}</th><th>{{ t('clusters.checkedAt') }}</th><th></th></tr></thead>
          <tbody><tr v-for="host in hosts" :key="host.id">
            <td><strong>{{ host.hostname || host.name }}</strong><small>{{ host.address }}:{{ host.port }}</small></td>
            <td><span class="state" :class="host.status"><i></i>{{ statusLabel(host.status) }}</span><small v-if="host.last_error">{{ host.last_error }}</small></td>
            <td><span class="state" :class="haClass(host)"><i></i>{{ haLabel(host) }}</span><small v-if="host.ha?.ha_product">{{ host.ha.ha_product }}</small><small v-else-if="host.ha?.inspection_error">{{ host.ha.inspection_error }}</small><small v-else-if="host.ha?.extension_error">{{ host.ha.extension_error }}</small></td>
            <td><div class="stack-status"><span :class="serviceClass(host,'pacemaker')">{{ t('clusters.pacemaker') }}: {{ serviceLabel(host,'pacemaker') }}</span><span :class="serviceClass(host,'corosync')">{{ t('clusters.corosync') }}: {{ serviceLabel(host,'corosync') }}</span><span :class="serviceClass(host,'hawk')">{{ t('clusters.hawk') }}: {{ serviceLabel(host,'hawk') }}</span><span :class="serviceClass(host,'hawk-backend')">{{ t('clusters.hawkBackend') }}: {{ serviceLabel(host,'hawk-backend') }}</span></div></td>
            <td><span class="state" :class="clusterStateClass(host)"><i></i>{{ t(clusterStateKey(host)) }}</span><small v-if="host.ha?.cluster_summary" class="cluster-summary">{{ host.ha.cluster_summary }}</small></td>
            <td>{{ host.cpu_count ? `${host.cpu_count} vCPU` : '—' }}<small>{{ memoryLabel(host.memory_total_bytes) }}</small></td>
            <td>{{ dateLabel(host.ha?.checked_at || host.last_checked_at) }}</td>
            <td class="action-cell"><div class="cell-action-controls"><button class="btn role-link btn-sm" @click="goToSubscriptions(host)">{{ t('clusters.manageSubscription') }}</button><span v-if="host.ha?.ha_active && haToolsInstalled(host)" class="state ready ha-tools-state"><i></i>{{ t('clusters.haToolsInstalled') }}</span><button v-else-if="host.ha?.ha_active" class="btn role-secondary btn-sm" :disabled="!canManageCluster || haToolBusyHostIds.includes(host.id)" :title="!canManageCluster ? t('clusters.operatorRoleRequired') : ''" @click="installHaTools(host)">{{ haToolBusyHostIds.includes(host.id) ? t('clusters.haToolsInstalling') : t('clusters.enableHaTools') }}</button><small v-if="!host.ha?.ha_active && host.ha?.ha_available">{{ t('clusters.activateHaAddonFirst') }}</small><div v-if="haToolResults[host.id]" class="ha-tool-result" :class="haToolResults[host.id].status"><span>{{ haToolResults[host.id].message || haToolResults[host.id].error }}</span><small v-if="haToolResults[host.id].status === 'installed'">{{ t('clusters.serviceActivationGuide') }}</small></div></div></td>
          </tr></tbody>
        </table></div>
        <p class="safety-note">{{ t('clusters.readOnlyNote') }}</p>
      </section>

      <section v-else-if="activeSection === 'templates'" id="cluster-panel-templates" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.templateCatalog') }}</span><h2>{{ t('clusters.templatesTitle') }}</h2><p>{{ t('clusters.templatesDescription') }}</p></div><button class="btn role-secondary" :disabled="preflightLoading || templateHostIds.length < 2" @click="runPreflight(templateHostIds)">{{ preflightLoading ? t('clusters.preflightRunning') : t('clusters.validateTemplates') }}</button></div>
        <div class="inline-callout info"><strong>{{ t('clusters.templatesUseExisting') }}</strong><p>{{ t('clusters.templatesUseExistingHelp') }}</p></div>
        <section class="template-host-selection" aria-labelledby="template-host-selection-title"><h3 id="template-host-selection-title">{{ t('clusters.templateSelectHosts') }}</h3><p class="section-help">{{ t('clusters.templateSelectHostsHelp') }}</p><div v-if="!templateCandidateHosts.length" class="inline-callout warning"><strong>{{ t('clusters.noEligibleHosts') }}</strong><p>{{ t('clusters.templateNoHostsHelp') }}</p></div><div v-else class="host-picker"><label v-for="host in templateCandidateHosts" :key="`template-${host.id}`" class="host-option"><input v-model="templateHostIds" type="checkbox" :value="host.id"><span><strong>{{ host.hostname || host.name }}</strong><small>{{ host.address }} · {{ haLabel(host) }}</small></span><span class="state" :class="templateHostIds.includes(host.id) ? 'ready' : 'unknown'"><i></i>{{ templateHostIds.includes(host.id) ? t('clusters.selected') : t('clusters.notSelected') }}</span></label></div><div v-if="templateHostIds.length < 2" class="inline-callout info"><strong>{{ t('clusters.selectAtLeastTwo') }}</strong><p>{{ t('clusters.templateNeedsTwoHosts') }}</p></div><div v-if="preflightError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.preflightError') }}</strong><p>{{ preflightError }}</p></div><small v-if="preflightResults.length" class="template-check-stamp">{{ t('clusters.templateCheckedAt', { time: dateLabel(preflightResults[0]?.checked_at) }) }}</small></section>
        <div class="template-grid" aria-live="polite">
          <article v-for="templateId in clusterTemplateIds" :key="templateId" class="cluster-template-card">
            <div class="template-card-heading"><div><span class="eyebrow">{{ t(`clusters.template_${templateId}_category`) }}</span><h3>{{ t(`clusters.template_${templateId}_title`) }}</h3></div><span class="state" :class="templateEvaluation(templateId).tone"><i></i>{{ t(`clusters.template_fit_${templateEvaluation(templateId).fit}`) }}</span></div>
            <p>{{ t(`clusters.template_${templateId}_description`) }}</p>
            <div class="template-card-summary"><span>{{ templateRequirementSummary(templateId) }}</span><span v-if="templateId === 'vm' && selectedTemplateHosts.length >= 2">{{ templateMinimumCapacity() }}</span></div>
            <div v-if="templateRemediation(templateId)" class="template-blocker"><span>{{ templateRemediationText(templateId) }}</span><button class="btn role-link btn-sm" :disabled="templateRemediationDisabled(templateId)" @click="runTemplateRemediation(templateId)">{{ templateRemediationLoading(templateId) ? t('clusters.templateResolving') : templateRemediationLabel(templateId) }}</button></div>
            <div v-if="templateHostIds.length >= 2 && !preflightResults.length" class="template-fix-empty"><span><strong>{{ t('clusters.templateFixesNeedCheck') }}</strong><small>{{ t('clusters.templateFixesNeedCheckHelp') }}</small></span><button class="btn role-secondary btn-sm" :disabled="preflightLoading" @click="runPreflight(templateHostIds)">{{ preflightLoading ? t('clusters.preflightRunning') : t('clusters.validateTemplates') }}</button></div>
            <section v-if="templateActionableRequirements(templateId).length" class="template-remediation-list" :aria-label="t('clusters.templateResolveRequirements')"><div class="template-remediation-heading"><strong>{{ t('clusters.templateFixesTitle') }}</strong><small>{{ t('clusters.templateFixesHelp') }}</small></div><div v-for="requirement in templateActionableRequirements(templateId)" :key="requirement.key" class="template-remediation-row"><span><strong>{{ requirement.text }}</strong><small>{{ templateRequirementHelp(templateId, requirement.key) }}</small></span><button class="btn role-secondary btn-sm" :aria-label="templateRequirementActionAriaLabel(templateId, requirement)" :title="!canManageCluster && templateRequirementActionDisabled(templateId, requirement.key) ? t('clusters.operatorRoleRequired') : ''" :disabled="templateRequirementActionDisabled(templateId, requirement.key)" @click="runTemplateRequirementAction(templateId, requirement.key)">{{ templateRequirementActionLabel(templateId, requirement.key) }}</button></div></section>
            <div v-if="templateHostActionResults(templateId).length" class="template-action-results" role="status" aria-live="polite"><p v-for="result in templateHostActionResults(templateId)" :key="result.host_id"><strong>{{ result.host_name }}:</strong> {{ result.message || result.error || operationStatusText(result.status) }}</p></div>
            <div v-if="templateResolveError && templateActionTemplateId === templateId" class="inline-callout warning template-resolve-error" role="alert">{{ templateResolveError }}</div>
            <details class="template-details"><summary>{{ t('clusters.templateRequirements') }} · {{ t('clusters.templateConfigurationPreview') }}</summary>
              <ul class="template-requirement-list"><li v-for="requirement in templateEvaluation(templateId).requirements" :key="requirement.key" :class="requirement.ok === null ? 'check-warning' : requirement.ok ? 'check-ok' : 'check-blocked'"><span>{{ requirement.text }}</span><small>{{ requirement.ok === null ? t('clusters.templateStatusPending') : requirement.ok ? t('clusters.templateStatusMet') : t('clusters.templateStatusMissing') }}</small></li></ul>
              <ul class="template-resource-flow"><li v-for="item in templatePreviewItems(templateId)" :key="item">{{ item }}</li></ul>
              <p class="template-manual-summary"><strong>{{ t('clusters.templateManualChecks') }}:</strong> {{ templateEvaluation(templateId).manual.join(' · ') }}</p>
            </details>
            <details v-if="templateEvaluation(templateId).hostChecks.length" class="template-details"><summary>{{ t('clusters.templateHostBreakdown') }}</summary><article v-for="hostCheck in templateEvaluation(templateId).hostChecks" :key="hostCheck.name" class="template-host-row"><div><strong>{{ hostCheck.name }}</strong><span class="state" :class="hostCheck.ok ? 'ready' : 'unreachable'"><i></i>{{ t(hostCheck.ok ? 'clusters.templateStatusMet' : 'clusters.templateStatusMissing') }}</span></div><ul><li v-for="item in hostCheck.evidence" :key="item">{{ item }}</li></ul><p v-if="hostCheck.nextSteps.length" class="template-next-step">{{ hostCheck.nextSteps.join(' · ') }}</p></article></details>
            <div class="template-card-footer"><button class="btn role-primary btn-sm" :disabled="templateEvaluation(templateId).fit !== 'candidate'" @click="useTemplate(templateId)">{{ t('clusters.useTemplate') }}</button></div>
          </article>
        </div>
        <p class="safety-note">{{ t('clusters.templatesSafety') }}</p>
      </section>

      <section v-else-if="activeSection === 'plan'" id="cluster-panel-plan" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.guidedSetup') }}</span><h2>{{ t('clusters.planTitle') }}</h2><p>{{ t('clusters.planDescription') }}</p></div><span class="planned-badge">{{ t('clusters.guidedWorkflowBadge') }}</span></div>
        <ol class="setup-steps" :aria-label="t('clusters.setupProgress')"><li v-for="(step, index) in setupSteps" :key="step" :class="{ current: setupStep === index, complete: setupStepComplete(index) }"><button type="button" :disabled="!canVisitSetupStep(index)" :aria-current="setupStep === index ? 'step' : undefined" @click="goToSetupStep(index)"><span class="step-number">{{ setupStepComplete(index) ? '✓' : index + 1 }}</span><span class="step-copy"><strong>{{ t(`clusters.setup_${step}`) }}</strong><small>{{ t(`clusters.setup_${step}_help`) }}</small></span></button></li></ol>
        <div class="plan-layout">
          <div class="plan-main">
            <div v-if="selectedTemplateId" class="inline-callout info selected-template-banner"><strong>{{ t('clusters.selectedTemplate', { template: t(`clusters.template_${selectedTemplateId}_title`) }) }}</strong><p>{{ t(`clusters.template_${selectedTemplateId}_description`) }}</p><button class="btn role-link btn-sm" @click="selectedTemplateId = ''">{{ t('clusters.clearTemplate') }}</button></div>
            <section v-if="setupStep === 0" class="setup-stage" aria-labelledby="setup-stage-title">
              <h3 id="setup-stage-title">{{ t('clusters.selectNodes') }}</h3><p class="section-help">{{ t('clusters.selectNodesHelp') }}</p>
              <div v-if="!eligibleHosts.length" class="inline-callout info"><strong>{{ t('clusters.noEligibleHosts') }}</strong><p>{{ t('clusters.noEligibleHostsHelp') }}</p><button class="btn role-link" @click="activeSection = 'overview'">{{ t('clusters.openNodes') }}</button></div>
              <div v-else class="host-picker"><label v-for="host in eligibleHosts" :key="host.id" class="host-option"><input v-model="selectedHostIds" type="checkbox" :value="host.id"><span><strong>{{ host.hostname || host.name }}</strong><small>{{ host.address }} · {{ host.ha?.ha_product_name || host.ha?.ha_product || t('clusters.haEnabled') }}</small></span><span class="state ready"><i></i>{{ t('clusters.readyForPlanning') }}</span></label></div>
              <div v-if="selectedHostIds.length < 2" class="inline-callout info" role="status"><strong>{{ t('clusters.selectAtLeastTwo') }}</strong><p>{{ t('clusters.selectAtLeastTwoHelp') }}</p></div>
            </section>

            <section v-else-if="setupStep === 1" class="setup-stage" aria-labelledby="setup-stage-title">
              <h3 id="setup-stage-title">{{ t('clusters.setup_preflight') }}</h3><p class="section-help">{{ t('clusters.preflightReadOnly') }}</p>
              <div class="preflight-actions"><button class="btn role-primary" :disabled="preflightLoading || selectedHostIds.length < 2" @click="runPreflight">{{ preflightLoading ? t('clusters.preflightRunning') : t('clusters.runPreflight') }}</button><small>{{ t('clusters.preflightScope', { count: selectedHostIds.length, hosts: selectedHostNames }) }}</small></div>
              <div v-if="preflightError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.preflightError') }}</strong><p>{{ preflightError }}</p></div>
              <div v-if="preflightResults.length" class="preflight-results"><h3>{{ t('clusters.preflightResults') }}</h3><article v-for="result in preflightResults" :key="result.host_id" class="preflight-host"><div class="preflight-host-heading"><strong>{{ result.host_name }}</strong><span class="state" :class="result.status === 'checked' ? 'ready' : 'unreachable'"><i></i>{{ result.status === 'checked' ? t('clusters.checked') : t('clusters.checkFailed') }}</span></div><p v-if="result.error" class="preflight-error-text">{{ result.error }}</p><template v-else-if="result.checks"><div class="preflight-facts"><span><small>{{ t('clusters.operatingSystem') }}</small><strong>{{ result.checks.os_name || result.checks.os_id || '—' }}</strong></span><span><small>{{ t('clusters.architecture') }}</small><strong>{{ result.checks.architecture || '—' }}</strong></span><span><small>{{ t('clusters.hostname') }}</small><strong>{{ result.checks.hostname || '—' }}</strong></span></div><ul class="preflight-checks"><li :class="result.checks.compatibility_supported ? 'check-ok' : 'check-blocked'">{{ result.checks.compatibility_supported ? t('clusters.compatibilitySupported') : t('clusters.compatibilityUnsupported') }}</li><li :class="result.checks.ha_active ? 'check-ok' : 'check-blocked'">{{ result.checks.ha_active ? t('clusters.haCheckOk') : t('clusters.haCheckMissing') }}</li><li :class="result.checks.time_synchronized ? 'check-ok' : 'check-warning'">{{ result.checks.time_synchronized ? t('clusters.timeCheckOk') : t('clusters.timeCheckUnknown') }}</li><li :class="result.checks.tools?.crm && result.checks.tools?.crm_mon ? 'check-ok' : 'check-warning'">{{ result.checks.tools?.crm && result.checks.tools?.crm_mon ? t('clusters.toolsCheckOk') : t('clusters.toolsCheckMissing') }}</li><li class="check-warning">{{ t('clusters.networkCheckManual', { count: result.checks.interfaces?.length || 0 }) }}</li><li class="check-warning">{{ t('clusters.fencingCheckManual', { count: result.checks.watchdog_devices?.length || 0 }) }}</li></ul></template></article><div v-if="preflightCompatibilityWarning" class="inline-callout warning"><strong>{{ t('clusters.compatibilityWarning') }}</strong><p>{{ preflightCompatibilityWarning }}</p></div><div v-if="!preflightReadyForBootstrap" class="inline-callout warning"><strong>{{ t('clusters.preflightHasBlockers') }}</strong><p>{{ t('clusters.preflightBlockerHelp') }}</p></div></div>
            </section>

            <section v-else-if="setupStep === 2" class="setup-stage" aria-labelledby="setup-stage-title">
              <h3 id="setup-stage-title">{{ t('clusters.topologyChoices') }}</h3><p class="section-help">{{ t('clusters.topologyChoicesHelp') }}</p>
              <div class="topology-fields"><label>{{ t('clusters.clusterName') }}<input v-model.trim="plannedClusterName" type="text" maxlength="64" :placeholder="t('clusters.clusterNamePlaceholder')" :aria-invalid="plannedClusterName.length > 0 && !validClusterName"></label><label>{{ t('clusters.quorumPlan') }}<select v-model="quorumPlan"><option value="pending">{{ t('clusters.chooseAfterPreflight') }}</option><option value="qdevice">{{ t('clusters.qdevicePlan') }}</option><option value="standard">{{ t('clusters.standardQuorum') }}</option></select></label><label>{{ t('clusters.fencingPlan') }}<select v-model="fencingPlan"><option value="pending">{{ t('clusters.chooseAfterPreflight') }}</option><option value="sbd">{{ t('clusters.sbdPlan') }}</option><option value="hardware">{{ t('clusters.externalFencingPlan') }}</option><option value="manual">{{ t('clusters.fencingPlanLater') }}</option></select></label></div>
              <div v-if="plannedClusterName && !validClusterName" class="inline-callout warning" role="alert"><strong>{{ t('clusters.clusterNameInvalid') }}</strong></div>
              <div v-if="selectedHostIds.length === 2" class="inline-callout warning" role="note"><strong>{{ t('clusters.twoNodeTitle') }}</strong><p>{{ t('clusters.twoNodeHelp') }}</p><p>{{ t('clusters.qnetdPlacement') }}</p></div><div v-else-if="selectedHostIds.length > 2 && selectedHostIds.length % 2 === 0" class="inline-callout info" role="note"><strong>{{ t('clusters.evenNodeTitle') }}</strong><p>{{ t('clusters.evenNodeHelp') }}</p><p>{{ t('clusters.qnetdPlacement') }}</p></div><div v-else-if="selectedHostIds.length >= 3" class="inline-callout success" role="status"><strong>{{ t('clusters.oddNodeTitle') }}</strong><p>{{ t('clusters.oddNodeHelp') }}</p></div>
              <div class="practice-grid"><article><span class="practice-mark">✓</span><div><strong>{{ t('clusters.practiceFailureDomains') }}</strong><p>{{ t('clusters.practiceFailureDomainsHelp') }}</p></div></article><article><span class="practice-mark">✓</span><div><strong>{{ t('clusters.practiceFencing') }}</strong><p>{{ t('clusters.practiceFencingHelp') }}</p></div></article><article><span class="practice-mark">✓</span><div><strong>{{ t('clusters.practiceNetwork') }}</strong><p>{{ t('clusters.practiceNetworkHelp') }}</p></div></article></div>
              <article v-if="selectedTemplateId" class="template-plan-preview"><span class="eyebrow">{{ t('clusters.templatePlanPreview') }}</span><h4>{{ t(`clusters.template_${selectedTemplateId}_title`) }}</h4><p>{{ t('clusters.templatePlanPreviewHelp') }}</p><ul><li v-for="item in templatePreviewItems(selectedTemplateId)" :key="item">{{ item }}</li></ul></article>
              <div class="inline-callout info"><strong>{{ t('clusters.planOnlyLabel') }}</strong><p>{{ t('clusters.topologyChoicesHelp') }}</p></div>
            </section>

            <section v-else-if="setupStep === 3" class="setup-stage" aria-labelledby="setup-stage-title">
              <h3 id="setup-stage-title">{{ t('clusters.reviewBeforeChanges') }}</h3><p class="section-help">{{ t('clusters.reviewBeforeChangesHelp') }}</p>
              <div class="review-grid"><article><h4>{{ t('clusters.reviewHosts') }}</h4><ul><li v-for="host in selectedClusterHosts" :key="host.id">{{ host.hostname || host.name }} <span>{{ host.address }}</span></li></ul></article><article><h4>{{ t('clusters.reviewTopology') }}</h4><dl><dt>{{ t('clusters.clusterName') }}</dt><dd>{{ plannedClusterName }}</dd><dt>{{ t('clusters.quorum') }}</dt><dd>{{ t(`clusters.quorum_${quorumPlan}`) }}</dd><dt>{{ t('clusters.fencing') }}</dt><dd>{{ t(`clusters.fencing_${fencingPlan}`) }}</dd><dt>{{ t('clusters.summaryNetworks') }}</dt><dd>{{ t('clusters.networkCheckManualSummary') }}</dd></dl></article><article v-if="selectedTemplateId" class="template-plan-preview"><h4>{{ t('clusters.templatePlanPreview') }} · {{ t(`clusters.template_${selectedTemplateId}_title`) }}</h4><ul><li v-for="item in templatePreviewItems(selectedTemplateId)" :key="item">{{ item }}</li></ul></article></div>
              <div class="inline-callout" :class="preflightReadyForBootstrap ? 'success' : 'warning'"><strong>{{ preflightReadyForBootstrap ? t('clusters.preflightReadyTitle') : t('clusters.preflightHasBlockers') }}</strong><p>{{ preflightReadyForBootstrap ? t('clusters.preflightReadyHelp') : t('clusters.preflightBlockerHelp') }}</p></div>
              <div class="stack-install"><div><strong>{{ t('clusters.installHaStackTitle') }}</strong><p>{{ haStackMissingHosts.length ? t('clusters.haStackMissingCount', { count: haStackMissingHosts.length, hosts: haStackMissingHostNames }) : t('clusters.haStackInstalledOnAll') }}</p></div><button v-if="canManageCluster && haStackMissingHosts.length" class="btn role-secondary" :disabled="stackInstallLoading || pendingInstallStack" @click="pendingInstallStack = true">{{ stackInstallLoading ? t('clusters.stackInstallRunning') : t('clusters.installHaStack') }}</button><span v-else-if="!canManageCluster" class="planned-badge">{{ t('clusters.operatorRoleRequired') }}</span><span v-else class="state ready"><i></i>{{ t('clusters.stackInstalled') }}</span></div>
              <div v-if="pendingInstallStack" class="inline-callout warning action-review"><strong>{{ t('clusters.installReviewTitle') }}</strong><p>{{ t('clusters.installReviewText', { hosts: haStackMissingHostNames }) }}</p><small>{{ t('clusters.installReviewWarning') }}</small><div><button class="btn role-primary btn-sm" :disabled="stackInstallLoading" @click="installHaStack">{{ stackInstallLoading ? t('clusters.stackInstallRunning') : t('clusters.confirmInstallHaStack') }}</button><button class="btn role-secondary btn-sm" :disabled="stackInstallLoading" @click="pendingInstallStack = false">{{ t('clusters.cancelAction') }}</button></div></div>
              <div v-if="stackInstallResults.length" class="preflight-results"><h3>{{ t('clusters.stackInstallResults') }}</h3><article v-for="item in stackInstallResults" :key="item.host_id" class="preflight-host"><div class="preflight-host-heading"><strong>{{ item.host_name }}</strong><span class="state" :class="item.status === 'installed' ? 'ready' : 'unreachable'"><i></i>{{ item.status === 'installed' ? t('clusters.stackInstalled') : t('clusters.stackInstallFailed') }}</span></div><p v-if="item.error" class="preflight-error-text">{{ item.error }}</p><p v-else class="section-help">{{ item.message }}</p></article></div>
              <div v-if="!validClusterName || quorumPlan === 'pending' || fencingPlan === 'pending' || fencingPlan === 'manual'" class="inline-callout warning"><strong>{{ t('clusters.reviewIncomplete') }}</strong><p>{{ t('clusters.reviewIncompleteHelp') }}</p></div><p class="safety-note">{{ t('clusters.planSafety') }}</p>
            </section>

            <section v-else class="setup-stage" aria-labelledby="setup-stage-title">
              <h3 id="setup-stage-title">{{ t('clusters.bootstrapTitle') }}</h3><p class="section-help">{{ t('clusters.bootstrapHelp') }}</p>
              <div v-if="!canStartBootstrap" class="inline-callout warning"><strong>{{ t('clusters.preflightRequiredForBootstrap') }}</strong><p>{{ t('clusters.bootstrapRequirements') }}</p></div>
              <div v-else class="bootstrap-guide"><article><div><strong>1 · {{ t('clusters.initializeFirstNode', { host: selectedClusterHosts[0].hostname || selectedClusterHosts[0].name }) }}</strong><button class="btn role-secondary btn-sm" @click="copyBootstrapCommand(initCommand)">{{ t('clusters.copyCommand') }}</button><button class="btn role-primary btn-sm" @click="openHostTerminal(selectedClusterHosts[0])">{{ t('clusters.openHostTerminal') }}</button></div><code>{{ initCommand }}</code></article><article v-for="host in selectedClusterHosts.slice(1)" :key="host.id"><div><strong>{{ t('clusters.joinAdditionalNode', { host: host.hostname || host.name }) }}</strong><button class="btn role-secondary btn-sm" @click="copyBootstrapCommand(joinCommand(host))">{{ t('clusters.copyCommand') }}</button><button class="btn role-primary btn-sm" @click="openHostTerminal(host)">{{ t('clusters.openHostTerminal') }}</button></div><code>{{ joinCommand(host) }}</code></article><span v-if="copyFeedback" role="status" class="copy-feedback">{{ copyFeedback }}</span></div>
              <VmConsole v-if="bootstrapTerminalHost" :host-id="bootstrapTerminalHost.id" :vm-name="bootstrapTerminalHost.hostname || bootstrapTerminalHost.name" :host-terminal="true" @close="closeBootstrapTerminal" />
              <div class="inline-callout warning"><strong>{{ t('clusters.bootstrapInteractiveTitle') }}</strong><p>{{ t('clusters.bootstrapInteractiveHelp', { quorum: t(`clusters.quorum_${quorumPlan}`), fencing: t(`clusters.fencing_${fencingPlan}`) }) }}</p></div><p class="safety-note">{{ t('clusters.bootstrapSafety') }}</p>
            </section>
          </div>
          <aside class="plan-summary"><span class="eyebrow">{{ t('clusters.setupStatus') }}</span><strong>{{ setupStep + 1 }} / {{ setupSteps.length }}</strong><p>{{ t(`clusters.setup_${setupSteps[setupStep]}`) }}</p><div class="summary-divider"></div><p><b>{{ t('clusters.reviewHosts') }}:</b> {{ selectedHostIds.length }} {{ t('clusters.selectedNodes') }}</p><p><b>{{ t('clusters.clusterName') }}:</b> {{ plannedClusterName || t('clusters.notChosen') }}</p><p><b>{{ t('clusters.quorum') }}:</b> {{ t(`clusters.quorum_${quorumPlan}`) }}</p><p><b>{{ t('clusters.fencing') }}:</b> {{ t(`clusters.fencing_${fencingPlan}`) }}</p><span class="state" :class="preflightReadyForBootstrap ? 'ready' : 'warning-state'"><i></i>{{ preflightReadyForBootstrap ? t('clusters.preflightReadyTitle') : t('clusters.preflightPendingLabel') }}</span></aside>
        </div>
        <footer class="setup-footer"><button class="btn role-secondary" :disabled="setupStep === 0" @click="goToSetupStep(setupStep - 1)">{{ t('clusters.previousStep') }}</button><span>{{ t('clusters.setupStepCounter', { current: setupStep + 1, total: setupSteps.length }) }}</span><button v-if="setupStep < setupSteps.length - 1" class="btn role-primary" :disabled="!canVisitSetupStep(setupStep + 1)" @click="goToSetupStep(setupStep + 1)">{{ t('clusters.nextStep') }}</button><button v-else class="btn role-primary" :disabled="loading" @click="checkClusterAfterSetup">{{ t('clusters.checkClusterStatus') }}</button></footer>
      </section>

      <section v-else :id="`cluster-panel-${activeSection}`" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t(`clusters.section_${activeSection}`) }}</h2><p>{{ t(`clusters.area_${activeSection}_description`) }}</p></div><span class="planned-badge">{{ t('clusters.availableAfterCluster') }}</span></div>
        <div class="section-preview"><div class="preview-icon" aria-hidden="true">{{ sectionIcon(activeSection) }}</div><div><h3>{{ t('clusters.sectionPreviewTitle') }}</h3><p>{{ t('clusters.sectionPreviewHelp') }}</p></div></div>
        <div v-if="activeSection === 'fencing'" class="inline-callout warning"><strong>{{ t('clusters.fencingRequiredTitle') }}</strong><p>{{ t('clusters.fencingRequiredHelp') }}</p></div>
        <div v-else-if="activeSection === 'nodes'" class="inline-callout info"><strong>{{ t('clusters.nodesPreviewTitle') }}</strong><p>{{ t('clusters.nodesPreviewHelp') }}</p><button class="btn role-link" @click="activeSection = 'overview'">{{ t('clusters.viewHostChecks') }}</button></div>
        <p class="safety-note">{{ t('clusters.hawkRoadmapSafety') }}</p>
      </section>
    </template>
  </div>
  </div>
</template>

<script lang="ts">
import { defineAsyncComponent, defineComponent } from 'vue';

const VmConsole = defineAsyncComponent(() => import(/* webpackChunkName: "kvm-vm-console" */ './VmConsole.vue'));

type HaStatus = { suseconnect_available?: boolean; ha_available?: boolean; ha_active?: boolean; ha_product?: string; ha_product_name?: string; extension_error?: string; commands?: Record<string, boolean>; services?: Record<string, string>; cluster_detected?: boolean; cluster_name?: string; cluster_identity?: string; cluster_members?: string[]; cluster_summary?: string; inspection_error?: string; checked_at?: string };
type Host = { id: string; name: string; address: string; port: number; hostname?: string; status: string; cpu_count?: number; memory_total_bytes?: number; last_checked_at?: string; last_error?: string; ha?: HaStatus };
type ClusterNode = { id: string; name: string; online: boolean; standby: boolean; maintenance: boolean; unclean: boolean; pending?: string };
type ClusterResource = { id: string; agent?: string; role?: string; active: boolean; failed: boolean; managed: boolean; nodes?: string[] };
type ClusterStatus = { cluster_name?: string; nodes: ClusterNode[]; resources: ClusterResource[]; node_count: number; online_count: number; resource_count: number; quorum?: { available?: boolean; quorate?: boolean; summary?: string }; fencing?: { available?: boolean; configured?: boolean; summary?: string }; checked_at?: string; source_host_id: string; source_host_name: string };
type ClusterDiagnostics = { checked_at?: string; hawk_url?: string; constraints?: Record<string,{available?:boolean;items?:string[];error?:string}>; corosync?: {available?:boolean;summary?:string;error?:string}; activity?: {available?:boolean;summary?:string;error?:string} };
type ResourceEditor = { mode: 'create' | 'edit'; resource_id: string; agent: string; parametersText: string; attributeType: 'param' | 'meta'; attributeAction: 'set' | 'delete'; key: string; value: string };
type ResourceMutation = { action: 'create' | 'set_param' | 'delete_param' | 'set_meta' | 'delete_meta' | 'delete'; resource_id: string; agent?: string; parameters?: Record<string,string>; key?: string; value?: string };
type ConstraintEditor = { action: 'create_location' | 'create_order' | 'create_colocation'; constraint_id: string; resource: string; other_resource: string; node: string; score: string; order_kind: 'Mandatory' | 'Optional' | 'Serialize' };
type ConstraintMutation = ConstraintEditor | { action: 'delete'; constraint_id: string };
type StackInstallResult = { host_id: string; host_name: string; status: string; message?: string; error?: string; services?: Record<string, { active?: string; enabled?: string }>; cluster_configured?: boolean };
type OperationJob = { job_id: string; kind: string; status: string; results: Array<StackInstallResult | TemplateResolveResult> };
type PreflightChecks = { os_id?: string; os_name?: string; os_version?: string; architecture?: string; compatibility_supported?: boolean; ha_active?: boolean; time_synchronized?: boolean; tools?: Record<string, boolean>; services?: Record<string, boolean>; time_services?: Record<string, string>; workload_services?: Record<string, boolean>; interfaces?: unknown[]; watchdog_devices?: unknown[]; resource_agents?: string[]; libvirt_pools?: string[]; libvirt_pool_details?: Array<{ name: string; type?: string; target_path?: string; source_path?: string; source_devices?: string[]; source_hosts?: string[] }> };
type PreflightResult = { host_id: string; host_name: string; status: string; checked_at?: string; error?: string; checks?: PreflightChecks };
type TemplateResolveResult = { host_id: string; host_name: string; action: string; status: string; message?: string; error?: string };
const apiBase = (process.env.VUE_APP_KVM_API || '/kvm-api').replace(/\/$/, '');

export default defineComponent({
  name: 'KvmClusters',
  components: { VmConsole },
  data() { return { hosts: [] as Host[], loading: false, loaded: false, error: '', refreshTimer: 0 as number, refreshingStale: false, activeSection: 'clusters', selectedHostIds: [] as string[], templateHostIds: [] as string[], selectedTemplateId: '', setupStep: 0, preflightLoading: false, preflightError: '', preflightResults: [] as PreflightResult[], templateResolveLoading: false, templateResolveError: '', templateResolveResults: [] as TemplateResolveResult[], templateActionTemplateId: '', pendingInstallStack: false, stackInstallLoading: false, stackInstallResults: [] as StackInstallResult[], haToolBusyHostIds: [] as string[], haToolsBatchLoading: false, haToolResults: {} as Record<string, StackInstallResult>, clusterStatus: null as ClusterStatus | null, activeClusterHostId: '', clusterStatusLoading: false, clusterStatusError: '', clusterDiagnostics: null as ClusterDiagnostics | null, clusterDiagnosticsError: '', diagnosticsLoading: false, plannedClusterName: '', quorumPlan: 'pending', fencingPlan: 'pending', copyFeedback: '', bootstrapTerminalHost: null as Host | null, pendingClusterAction: null as null | { action: string; target: string }, clusterActionBusy: false, clusterActionError: '', clusterActionMessage: '', resourceAgents: [] as string[], resourceAgentsError: '', resourceAgentInfo: '', resourceEditor: null as ResourceEditor | null, pendingResourceMutation: null as ResourceMutation | null, resourceMutationBusy: false, resourceMutationError: '', resourceMutationMessage: '', constraintEditor: null as ConstraintEditor | null, pendingConstraintMutation: null as ConstraintMutation | null, constraintMutationBusy: false, constraintMutationError: '', constraintMutationMessage: '', canManageCluster: false, sections: ['clusters','templates','nodes','resources','constraints','activity','fencing','plan','overview'], clusterTemplateIds: ['service','vm','web','nfs'], setupSteps: ['nodes','preflight','topology','review','configure'] }; },
  watch: { selectedHostIds() { this.preflightResults = []; this.preflightError = ''; this.setupStep = 0; }, templateHostIds(ids: string[]) { this.preflightResults = []; this.preflightError = ''; this.templateResolveResults = []; this.templateResolveError = ''; try { if (ids.length) sessionStorage.setItem('kvm-template-host-ids', JSON.stringify(ids)); else sessionStorage.removeItem('kvm-template-host-ids'); } catch { /* Storage can be disabled by browser policy; selection still works for this page visit. */ } } },
  mounted() { try { const saved = JSON.parse(sessionStorage.getItem('kvm-template-host-ids') || '[]'); if (Array.isArray(saved)) this.templateHostIds = saved.filter((id): id is string => typeof id === 'string'); } catch { /* Ignore invalid or unavailable saved selection. */ } this.load(); this.refreshTimer = window.setInterval(() => { if (document.visibilityState === 'visible') this.refreshStale(); }, 60000); },
  beforeUnmount() { window.clearInterval(this.refreshTimer); },
  computed: {
    haEnabledCount(): number { return this.hosts.filter((host) => host.ha?.ha_active).length; },
    haToolsEligibleHosts(): Host[] { return this.hosts.filter((host) => host.status === 'ready' && host.ha?.ha_active && !this.haToolsInstalled(host) && !this.haToolBusyHostIds.includes(host.id)); },
    clusterHostCount(): number { return this.clusterHosts.length; },
    clusterHosts(): Host[] { const seen = new Set<string>(); return this.hosts.filter((host) => { const identity = host.ha?.cluster_identity; if (!host.ha?.cluster_detected || !identity) return false; if (seen.has(identity)) return false; seen.add(identity); return true; }); },
    templateCandidateHosts(): Host[] { return this.hosts.filter((host) => host.status === 'ready' && !host.ha?.cluster_detected); },
    quorumSummary(): string { const value = this.clusterStatus?.quorum?.summary?.split('\n').find((line) => /quorate|quorum|votes|expected/i.test(line)); return value?.trim() || this.t('clusters.quorumHelp'); },
    fencingSummary(): string { const value = this.clusterStatus?.fencing?.summary?.trim(); return value ? value.split('\n').slice(0,2).join(' · ') : this.t('clusters.fencingHelp'); },
    actionReviewText(): string { if (!this.pendingClusterAction) return ''; return this.t(`clusters.review_${this.pendingClusterAction.action}`, { target: this.pendingClusterAction.target }); },
    resourceMutationSummary(): string { const change = this.pendingResourceMutation; if (!change) return ''; if (change.action === 'create') return this.t('clusters.reviewCreateResource', { id: change.resource_id, agent: change.agent || '', count: Object.keys(change.parameters || {}).length }); if (change.action === 'delete') return this.t('clusters.reviewDeleteResource', { id: change.resource_id }); return this.t('clusters.reviewEditResource', { id: change.resource_id, attribute: change.key || '', action: change.action.startsWith('delete_') ? this.t('clusters.deleteAttribute').toLowerCase() : this.t('clusters.updateAttribute').toLowerCase() }); },
    constraintMutationSummary(): string { const change = this.pendingConstraintMutation; if (!change) return ''; if (change.action === 'delete') return this.t('clusters.reviewDeleteConstraint', { id: change.constraint_id }); return this.t('clusters.reviewCreateConstraint', { id: change.constraint_id, kind: this.t(`clusters.${change.action}`), resource: change.resource, other: change.other_resource || change.node || '', score: change.score || '' }); },
    selectedHostNames(): string { return this.hosts.filter((host) => this.selectedHostIds.includes(host.id)).map((host) => host.hostname || host.name).join(', '); },
    selectedClusterHosts(): Host[] { return this.selectedHostIds.map((id) => this.hosts.find((host) => host.id === id)).filter((host): host is Host => Boolean(host)); },
    selectedTemplateHosts(): Host[] { return this.templateHostIds.map((id) => this.hosts.find((host) => host.id === id)).filter((host): host is Host => Boolean(host)); },
    haStackMissingHosts(): Host[] { return this.selectedClusterHosts.filter((host) => !this.haToolsInstalled(host)); },
    haStackMissingHostNames(): string { return this.haStackMissingHosts.map((host) => host.hostname || host.name).join(', '); },
    validClusterName(): boolean { return /^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/.test(this.plannedClusterName); },
    preflightComplete(): boolean { return this.selectedHostIds.length >= 2 && this.selectedHostIds.every((id) => this.preflightResults.some((result) => result.host_id === id)); },
    topologyReady(): boolean { return this.validClusterName && this.quorumPlan !== 'pending' && this.fencingPlan !== 'pending' && this.fencingPlan !== 'manual'; },
    preflightReadyForBootstrap(): boolean { return this.selectedHostIds.length >= 2 && !this.preflightArchitectureMismatch && this.preflightResults.length === this.selectedHostIds.length && this.selectedHostIds.every((id) => this.preflightResults.some((result) => result.host_id === id && result.status === 'checked' && result.checks?.compatibility_supported && result.checks?.ha_active && result.checks?.time_synchronized && result.checks?.tools?.crm && result.checks?.tools?.crm_mon)); },
    canStartBootstrap(): boolean { return this.preflightReadyForBootstrap && this.topologyReady && this.haStackMissingHosts.length === 0; },
    initCommand(): string { return `sudo crm cluster init --name ${this.shellArg(this.plannedClusterName)}`; },
    eligibleHosts(): Host[] { return this.hosts.filter((host) => host.status === 'ready' && host.ha?.ha_active && !host.ha?.cluster_detected); },
    preflightArchitectureMismatch(): boolean { const architectures = [...new Set(this.preflightResults.filter((item) => item.checks).map((item) => item.checks!.architecture).filter(Boolean))]; return architectures.length > 1; },
    preflightCompatibilityWarning(): string { const checked = this.preflightResults.filter((item) => item.checks).map((item) => item.checks!); if (checked.length < 2) return ''; const architectures = [...new Set(checked.map((item) => item.architecture).filter(Boolean))]; const releases = [...new Set(checked.map((item) => `${item.os_id}:${item.os_version}`).filter((item) => item !== ':'))]; const issues = [architectures.length > 1 ? this.t('clusters.architectureMismatch') : '', releases.length > 1 ? this.t('clusters.releaseMismatch') : ''].filter(Boolean); return issues.join(' '); },
  },
  methods: {
    t(key: string, args?: Record<string, unknown>): string { const translate = (this as any).$store?.getters?.['i18n/t']; return translate ? translate(`kvmManager.${key}`, args) : key; },
    setupStepComplete(index: number): boolean { if (index === 0) return this.selectedHostIds.length >= 2; if (index === 1) return this.preflightComplete && this.preflightReadyForBootstrap; if (index === 2) return this.topologyReady; if (index === 3) return this.canStartBootstrap; return this.clusterHostCount > 0; },
    canVisitSetupStep(index: number): boolean { if (index <= this.setupStep) return true; if (index === 0) return true; if (index === 1) return this.selectedHostIds.length >= 2; if (index === 2) return this.preflightComplete; if (index === 3) return this.preflightComplete && this.topologyReady; if (index === 4) return this.canStartBootstrap; return false; },
    goToSetupStep(index: number) { if (index >= 0 && index < this.setupSteps.length && this.canVisitSetupStep(index)) this.setupStep = index; },
    async checkClusterAfterSetup() { this.activeSection = 'clusters'; await this.load(); },
    async load() { this.loading = true; this.error = ''; try { await Promise.all([this.fetchReadiness(), this.fetchPermissions()]); } catch (error) { this.error = `${this.t('clusters.loadError')}: ${(error as Error).message}`; } finally { this.loading = false; this.loaded = true; } },
    async fetchPermissions() { try { const response = await fetch(`${apiBase}/permissions`, { credentials: 'include', cache: 'no-store' }); if (response.ok) { const body = await response.json(); this.canManageCluster = Boolean(body.canManageClusters || body.canManageHostResources || body.canAdministerHost); } } catch { this.canManageCluster = false; } },
    async fetchReadiness() { const response = await fetch(`${apiBase}/clusters/readiness`, { credentials: 'include', cache: 'no-store' }); if (!response.ok) { const body = await response.json().catch(() => ({})); throw new Error(body.detail || `API request failed (${response.status})`); } this.hosts = await response.json(); const retainedHostIds = this.selectedHostIds.filter((id) => this.eligibleHosts.some((host) => host.id === id)); if (retainedHostIds.length !== this.selectedHostIds.length) this.selectedHostIds = retainedHostIds; const retainedTemplateHostIds = this.templateHostIds.filter((id) => this.templateCandidateHosts.some((host) => host.id === id)); if (retainedTemplateHostIds.length !== this.templateHostIds.length) this.templateHostIds = retainedTemplateHostIds; const source = this.clusterHosts.find((host) => host.id === this.activeClusterHostId) || this.clusterHosts[0]; if (source && !this.clusterStatusLoading) { this.activeClusterHostId = source.id; await this.fetchClusterStatus(); } else if (!source) { this.activeClusterHostId = ''; this.clusterStatus = null; this.clusterStatusError = ''; } },
    async fetchClusterStatus() { if (!this.activeClusterHostId) return; this.clusterStatusLoading = true; this.clusterStatusError = ''; try { const response = await fetch(`${apiBase}/clusters/${encodeURIComponent(this.activeClusterHostId)}/status`, { credentials: 'include', cache: 'no-store' }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); this.clusterStatus = body; } catch (error) { this.clusterStatus = null; this.clusterStatusError = (error as Error).message; } finally { this.clusterStatusLoading = false; } },
    async fetchClusterDiagnostics() { if (!this.activeClusterHostId) return; this.diagnosticsLoading = true; this.clusterDiagnosticsError = ''; try { const response = await fetch(`${apiBase}/clusters/${encodeURIComponent(this.activeClusterHostId)}/diagnostics`, { credentials: 'include', cache: 'no-store' }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); this.clusterDiagnostics = body; } catch (error) { this.clusterDiagnostics = null; this.clusterDiagnosticsError = (error as Error).message; } finally { this.diagnosticsLoading = false; } },
    async selectSection(section: string) { this.activeSection = section; if ((section === 'constraints' || section === 'activity' || section === 'fencing') && this.activeClusterHostId) await this.fetchClusterDiagnostics(); },
    onNavigationKeydown(event: KeyboardEvent, index: number) { let next = index; if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % this.sections.length; else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') next = (index - 1 + this.sections.length) % this.sections.length; else if (event.key === 'Home') next = 0; else if (event.key === 'End') next = this.sections.length - 1; else return; event.preventDefault(); const section = this.sections[next]; this.selectSection(section); this.$nextTick(() => document.getElementById(`cluster-tab-${section}`)?.focus()); },
    selectSectionFromPicker(event: Event) { const value = (event.target as HTMLSelectElement).value; this.selectSection(value); },
    shellArg(value: string): string { return `'${value.replace(/'/g, "'\\''")}'`; },
    joinCommand(host: Host): string { const first = this.selectedClusterHosts[0]; return `sudo crm cluster join --cluster-node ${this.shellArg(first.hostname || first.name)}`; },
    openHostTerminal(host: Host) { this.bootstrapTerminalHost = host; },
    async closeBootstrapTerminal() { this.bootstrapTerminalHost = null; await this.fetchReadiness(); },
    async copyBootstrapCommand(command: string) { try { await navigator.clipboard.writeText(command); this.copyFeedback = this.t('clusters.commandCopied'); window.setTimeout(() => { this.copyFeedback = ''; }, 2500); } catch { this.copyFeedback = this.t('clusters.copyFailed'); } },
    async openCluster(host: Host) { this.activeClusterHostId = host.id; this.clusterActionError = ''; this.clusterActionMessage = ''; await Promise.all([this.fetchClusterStatus(), this.fetchClusterDiagnostics()]); if (this.clusterStatus) this.activeSection = 'nodes'; },
    requestClusterAction(action: string, target: string) { if (!this.canManageCluster) return; this.pendingClusterAction = { action, target }; this.clusterActionError = ''; this.clusterActionMessage = ''; },
    async runClusterAction() { if (!this.pendingClusterAction || !this.activeClusterHostId) return; const action = this.pendingClusterAction; this.clusterActionBusy = true; this.clusterActionError = ''; this.clusterActionMessage = ''; try { const response = await fetch(`${apiBase}/clusters/${encodeURIComponent(this.activeClusterHostId)}/actions`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(action) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); this.clusterActionMessage = body.message || this.t('clusters.actionSucceeded'); this.pendingClusterAction = null; await this.fetchClusterStatus(); } catch (error) { this.clusterActionError = (error as Error).message; } finally { this.clusterActionBusy = false; } },
    async openCreateResource() { this.resourceMutationError = ''; this.resourceMutationMessage = ''; this.resourceAgentInfo = ''; this.resourceEditor = { mode: 'create', resource_id: '', agent: '', parametersText: '', attributeType: 'param', attributeAction: 'set', key: '', value: '' }; await this.loadResourceAgents(); },
    async loadResourceAgents() { if (!this.activeClusterHostId) return; this.resourceAgentsError = ''; try { const response = await fetch(`${apiBase}/clusters/${encodeURIComponent(this.activeClusterHostId)}/resource-agents`, { credentials: 'include', cache: 'no-store' }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); this.resourceAgents = Array.isArray(body.agents) ? body.agents : []; if (!this.resourceAgents.length) this.resourceAgentsError = this.t('clusters.resourceAgentsEmpty'); } catch (error) { this.resourceAgentsError = (error as Error).message; } },
    async loadResourceAgentInfo() { if (!this.activeClusterHostId || !this.resourceEditor?.agent) { this.resourceAgentInfo = ''; return; } this.resourceAgentsError = ''; try { const query = new URLSearchParams({ agent: this.resourceEditor.agent }); const response = await fetch(`${apiBase}/clusters/${encodeURIComponent(this.activeClusterHostId)}/resource-agent-info?${query}`, { credentials: 'include', cache: 'no-store' }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); this.resourceAgentInfo = body.info || ''; } catch (error) { this.resourceAgentsError = (error as Error).message; } },
    openResourceEditor(resource: ClusterResource) { this.resourceMutationError = ''; this.resourceMutationMessage = ''; this.resourceEditor = { mode: 'edit', resource_id: resource.id, agent: resource.agent || '', parametersText: '', attributeType: 'param', attributeAction: 'set', key: '', value: '' }; },
    parseResourceParameters(value: string): Record<string,string> { const result: Record<string,string> = {}; for (const [index, raw] of value.split('\n').entries()) { const line = raw.trim(); if (!line || line.startsWith('#')) continue; const divider = line.indexOf('='); if (divider < 1) throw new Error(this.t('clusters.resourceParameterFormat', { line: index + 1 })); const key = line.slice(0, divider).trim(); const item = line.slice(divider + 1).trim(); if (!/^[A-Za-z_][A-Za-z0-9_.-]{0,63}$/.test(key) || !item || /[\r\n\0]/.test(item)) throw new Error(this.t('clusters.resourceParameterFormat', { line: index + 1 })); result[key] = item; } return result; },
    prepareResourceCreate() { if (!this.resourceEditor || this.resourceEditor.mode !== 'create') return; try { const parameters = this.parseResourceParameters(this.resourceEditor.parametersText); this.pendingResourceMutation = { action: 'create', resource_id: this.resourceEditor.resource_id, agent: this.resourceEditor.agent, parameters }; this.resourceMutationError = ''; this.resourceMutationMessage = ''; } catch (error) { this.resourceMutationError = (error as Error).message; } },
    prepareResourceEdit() { if (!this.resourceEditor || this.resourceEditor.mode !== 'edit') return; const editor = this.resourceEditor; const action = `${editor.attributeAction}_${editor.attributeType}` as ResourceMutation['action']; this.pendingResourceMutation = { action, resource_id: editor.resource_id, key: editor.key, ...(editor.attributeAction === 'set' ? { value: editor.value } : {}) }; this.resourceMutationError = ''; this.resourceMutationMessage = ''; },
    prepareResourceDelete(resource: ClusterResource) { this.resourceEditor = null; this.pendingResourceMutation = { action: 'delete', resource_id: resource.id }; this.resourceMutationError = ''; this.resourceMutationMessage = ''; },
    async runResourceMutation() { if (!this.pendingResourceMutation || !this.activeClusterHostId || !this.canManageCluster) return; const payload = this.pendingResourceMutation; this.resourceMutationBusy = true; this.resourceMutationError = ''; this.resourceMutationMessage = ''; try { const response = await fetch(`${apiBase}/clusters/${encodeURIComponent(this.activeClusterHostId)}/resources/config`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); this.resourceMutationMessage = body.message || this.t('clusters.resourceChangeSucceeded'); this.pendingResourceMutation = null; this.resourceEditor = null; await this.fetchClusterStatus(); await this.fetchClusterDiagnostics(); } catch (error) { this.resourceMutationError = (error as Error).message; } finally { this.resourceMutationBusy = false; } },
    openConstraintEditor(action: ConstraintEditor['action']) { this.constraintMutationError = ''; this.constraintMutationMessage = ''; this.constraintEditor = { action, constraint_id: '', resource: '', other_resource: '', node: '', score: action === 'create_order' ? '' : 'INFINITY', order_kind: 'Mandatory' }; },
    changeConstraintType(event: Event) { const action = (event.target as HTMLSelectElement).value as ConstraintEditor['action']; if (!['create_location','create_order','create_colocation'].includes(action)) return; this.openConstraintEditor(action); },
    prepareConstraintMutation() { if (!this.constraintEditor) return; const value = this.constraintEditor; if (!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/.test(value.constraint_id) || !value.resource) { this.constraintMutationError = this.t('clusters.constraintInvalid'); return; } if (value.action !== 'create_location' && (!value.other_resource || value.other_resource === value.resource)) { this.constraintMutationError = this.t('clusters.constraintInvalid'); return; } if (value.action === 'create_location' && !value.node) { this.constraintMutationError = this.t('clusters.constraintInvalid'); return; } if (value.action !== 'create_order' && value.score !== 'INFINITY' && value.score !== '-INFINITY' && !/^-?\d{1,9}$/.test(value.score)) { this.constraintMutationError = this.t('clusters.constraintInvalid'); return; } this.pendingConstraintMutation = { ...value }; this.constraintMutationError = ''; this.constraintMutationMessage = ''; },
    constraintId(item: string): string { const parts = item.trim().split(/\s+/); return ['location','order','colocation'].includes(parts[0]) ? (parts[1] || '') : (parts[0] || ''); },
    prepareConstraintDelete(item: string) { const constraint_id = this.constraintId(item); if (!constraint_id) return; this.constraintEditor = null; this.pendingConstraintMutation = { action: 'delete', constraint_id }; this.constraintMutationError = ''; this.constraintMutationMessage = ''; },
    async runConstraintMutation() { if (!this.pendingConstraintMutation || !this.activeClusterHostId || !this.canManageCluster) return; const payload = this.pendingConstraintMutation; this.constraintMutationBusy = true; this.constraintMutationError = ''; this.constraintMutationMessage = ''; try { const response = await fetch(`${apiBase}/clusters/${encodeURIComponent(this.activeClusterHostId)}/constraints/config`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); this.constraintMutationMessage = body.message || this.t('clusters.constraintMutationSucceeded'); this.pendingConstraintMutation = null; this.constraintEditor = null; await this.fetchClusterStatus(); await this.fetchClusterDiagnostics(); } catch (error) { this.constraintMutationError = (error as Error).message; } finally { this.constraintMutationBusy = false; } },
    async runPreflight(hostIds?: string[]) { const targets = hostIds || this.selectedHostIds; if (targets.length < 2) return; this.preflightLoading = true; this.preflightError = ''; this.preflightResults = []; try { const response = await fetch(`${apiBase}/clusters/preflight`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ host_ids: targets }) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); this.preflightResults = body; } catch (error) { this.preflightError = (error as Error).message; } finally { this.preflightLoading = false; } },
    templateEvaluation(templateId: string): { fit: string; tone: string; requirements: { key: string; text: string; ok: boolean | null }[]; manual: string[]; hostChecks: { name: string; ok: boolean; evidence: string[]; nextSteps: string[] }[] } {
      const selected = this.selectedTemplateHosts;
      const results = selected.map((host) => this.preflightResults.find((result) => result.host_id === host.id));
      const checked = results.length >= 2 && results.every((result) => result?.status === 'checked' && result.checks);
      const checks = results.map((result) => result?.checks).filter((item): item is PreflightChecks => Boolean(item));
      const haReady = checked && checks.every((item) => item.compatibility_supported && item.ha_active && item.tools?.crm && item.tools?.crm_mon);
      const sameArch = new Set(checks.map((item) => item.architecture).filter(Boolean)).size <= 1;
      const sameRelease = new Set(checks.map((item) => `${item.os_id}:${item.os_version}`)).size <= 1;
      const timeReady = checked && checks.every((item) => item.time_synchronized === true);
      const baseReady = Boolean(haReady && sameArch && sameRelease && timeReady);
      const agentAvailableOnAll = (agent: string) => checked && checks.every((item) => (item.resource_agents || []).includes(agent));
      const templateAgents: Record<string, string[]> = { service: ['heartbeat:IPaddr2'], vm: ['heartbeat:VirtualDomain'], web: ['heartbeat:apache'], nfs: ['heartbeat:Filesystem','heartbeat:exportfs','heartbeat:nfsserver','heartbeat:IPaddr2'] };
      const requiredAgents = templateAgents[templateId] || [];
      const agentFit = requiredAgents.length ? requiredAgents.every(agentAvailableOnAll) : checked;
      const applicationService = templateId === 'web' ? 'apache2' : templateId === 'nfs' ? 'nfsserver' : '';
      const applicationServiceFit = !applicationService || (checked && checks.every((item) => item.workload_services?.[applicationService]));
      const requirements = [
        { key: 'nodes', text: this.t('clusters.templateReqTwoNodes'), ok: selected.length >= 2 },
        { key: 'connectivity', text: this.t('clusters.templateReqConnectivity'), ok: checked ? true : results.some((result) => result?.status === 'error') ? false : null },
        { key: 'ha', text: this.t('clusters.templateReqSuseHa'), ok: checked ? Boolean(haReady) : null },
        { key: 'compatibility', text: this.t('clusters.templateReqCompatibility'), ok: checked ? Boolean(checks.every((item) => item.compatibility_supported) && sameArch && sameRelease) : null },
        { key: 'tools', text: this.t('clusters.templateReqTools'), ok: checked ? Boolean(checks.every((item) => item.tools?.crm && item.tools?.crm_mon)) : null },
        { key: 'time', text: this.t('clusters.templateReqTimeSync'), ok: checked ? Boolean(timeReady) : null },
        { key: 'agents', text: this.t('clusters.templateReqAgents', { agents: requiredAgents.join(', ') }), ok: checked ? agentFit : null },
        ...(templateId === 'vm' ? [{ key: 'pool', text: this.t('clusters.templateReqLibvirtStorage', { count: (checks.length ? Math.min(...checks.map((item) => item.libvirt_pools?.length || 0)) : 0) }), ok: checked ? checks.every((item) => Boolean(item.libvirt_pools?.length)) : null }] : []),
        ...(applicationService ? [{ key: 'app', text: this.t(templateId === 'web' ? 'clusters.templateReqApache' : 'clusters.templateReqNfsServer'), ok: checked ? Boolean(applicationServiceFit) : null }] : []),
      ];
      const manual = [this.t('clusters.templateReqFencing'), this.t('clusters.templateReqNetwork'), this.t('clusters.templateReqQuorum')];
      if (templateId === 'vm') manual.push(this.t('clusters.templateReqVmStorage'));
      if (templateId === 'service') manual.push(this.t('clusters.templateReqApplication'));
      if (templateId === 'web') manual.push(this.t('clusters.templateReqWebConfig'));
      if (templateId === 'nfs') manual.push(this.t('clusters.templateReqNfsStorage'));
      const hostChecks = this.preflightResults.length ? results.map((result, index) => {
        const host = selected[index];
        const facts = result?.checks;
        const agentsOk = Boolean(facts && requiredAgents.every((agent) => (facts.resource_agents || []).includes(agent)));
        const serviceOk = !applicationService || Boolean(facts?.workload_services?.[applicationService]);
        const poolOk = templateId !== 'vm' || Boolean(facts?.libvirt_pools?.length);
        const ok = Boolean(result?.status === 'checked' && facts?.compatibility_supported && facts?.ha_active && facts?.tools?.crm && facts?.tools?.crm_mon && facts?.time_synchronized && agentsOk && serviceOk && poolOk);
        const nextSteps: string[] = [];
        if (result?.status !== 'checked') nextSteps.push(this.t('clusters.templateNextCheckConnectivity'));
        else {
          if (!facts?.compatibility_supported) nextSteps.push(this.t('clusters.templateNextCheckSles'));
          if (!facts?.ha_active) nextSteps.push(this.t('clusters.templateNextActivateHa'));
          if (!facts?.tools?.crm || !facts?.tools?.crm_mon) nextSteps.push(this.t('clusters.templateNextInstallTools'));
          if (!facts?.time_synchronized) nextSteps.push(this.t('clusters.templateNextSyncTime'));
          if (!agentsOk) nextSteps.push(this.t('clusters.templateNextInstallAgents'));
          if (!poolOk) nextSteps.push(this.t('clusters.templateNextConfigurePool'));
          if (!serviceOk) nextSteps.push(this.t('clusters.templateNextInstallService', { service: applicationService }));
        }
        const evidence = facts ? [
          this.t(facts.compatibility_supported ? 'clusters.templateStatusSlesOk' : 'clusters.templateStatusSlesMissing', { version: `${facts.os_name || facts.os_id || 'SLES'} ${facts.os_version || ''}` }),
          this.t(facts.ha_active ? 'clusters.templateStatusHaOk' : 'clusters.templateStatusHaMissing'),
          this.t(facts.time_synchronized ? 'clusters.templateStatusTimeOk' : 'clusters.templateStatusTimeMissing'),
          this.t('clusters.templateStatusAgentEvidence', { count: (facts.resource_agents || []).filter((agent) => requiredAgents.includes(agent)).length, total: requiredAgents.length }),
          ...(templateId === 'vm' ? [this.t('clusters.templateStatusPoolEvidence', { pools: (facts.libvirt_pool_details || []).map((pool) => `${pool.name} (${pool.type || 'unknown'}${pool.source_path ? ` · ${pool.source_path}` : ''}${pool.source_hosts?.length ? ` · ${pool.source_hosts.join(', ')}` : ''})`).join('; ') || this.t('clusters.noneDetected') })] : []),
          ...(applicationService ? [this.t(serviceOk ? 'clusters.templateStatusAppOk' : 'clusters.templateStatusAppMissing', { service: applicationService })] : []),
        ] : [result?.error || this.t('clusters.templateStatusNoPreflight')];
        return { name: host?.hostname || host?.name || result?.host_name || '', ok, evidence, nextSteps };
      }) : [];
      let fit = 'not_checked';
      if (selected.length < 2) fit = 'select_hosts';
      else if (this.preflightResults.length) fit = baseReady && agentFit && applicationServiceFit && (templateId !== 'vm' || checks.every((item) => Boolean(item.libvirt_pools?.length))) ? 'candidate' : 'not_compatible';
      return { fit, tone: fit === 'candidate' ? 'ready' : fit === 'not_compatible' ? 'unreachable' : 'unknown', requirements, manual, hostChecks };
    },
    useTemplate(templateId: string) { if (this.templateEvaluation(templateId).fit !== 'candidate') return; this.selectedTemplateId = templateId; this.setupStep = 0; this.activeSection = 'plan'; },
    templateRequirementSummary(templateId: string): string {
      const evaluation = this.templateEvaluation(templateId);
      const met = evaluation.requirements.filter((item) => item.ok === true).length;
      const pending = evaluation.requirements.filter((item) => item.ok === null).length;
      return pending ? this.t('clusters.templateSummaryPending', { count: pending }) : this.t('clusters.templateSummaryMet', { met, total: evaluation.requirements.length });
    },
    firstTemplateBlocker(templateId: string): string {
      const blocker = this.templateEvaluation(templateId).requirements.find((item) => item.ok === false);
      return blocker?.text || this.t('clusters.templateReviewPrerequisites');
    },
    templateActionableRequirements(templateId: string): { key: string; text: string; ok: boolean | null }[] {
      return this.templateEvaluation(templateId).requirements.filter((item) => item.ok === false);
    },
    templateRequirementHelp(templateId: string, key: string): string {
      const remedy = this.templateRequirementRemedy(templateId, key);
      return this.t(`clusters.templateResolveHelp_${remedy.type}`);
    },
    templateRequirementActionLabel(templateId: string, key: string): string {
      const remedy = this.templateRequirementRemedy(templateId, key);
      return remedy.hostIds?.length ? this.t('clusters.templateFixHostsButton', { count: remedy.hostIds.length }) : this.t('clusters.templateFixButton');
    },
    templateRequirementActionAriaLabel(templateId: string, requirement: { key: string; text: string }): string { return `${this.templateRequirementActionLabel(templateId, requirement.key)}: ${requirement.text}`; },
    templateRequirementActionDisabled(templateId: string, key: string): boolean {
      const remedy = this.templateRequirementRemedy(templateId, key);
      if (remedy.type === 'preflight') return this.preflightLoading;
      if (remedy.type === 'ha_stack') return !this.canManageCluster || this.haToolsBatchLoading || this.haToolBusyHostIds.length > 0;
      if (remedy.type === 'time_sync' || remedy.type === 'workload_package') return !this.canManageCluster || this.templateResolveLoading;
      return false;
    },
    templateRequirementRemedy(templateId: string, key: string): { type: string; hostId?: string; hostIds?: string[]; action?: string } {
      const hosts = this.selectedTemplateHosts;
      if (key === 'nodes' || hosts.length < 2) return { type: 'select_hosts' };
      const checks = hosts.map((host) => this.preflightResults.find((item) => item.host_id === host.id));
      if (key === 'connectivity') {
        const failed = checks.find((item) => item?.status === 'error');
        return failed ? { type: 'host_connectivity', hostId: failed.host_id } : { type: 'preflight' };
      }
      if (checks.some((item) => item?.status !== 'checked' || !item.checks)) return { type: 'preflight' };
      if (key === 'ha') {
        const host = hosts.find((_, index) => !checks[index]?.checks?.ha_active);
        if (host) return { type: 'subscription', hostId: host.id };
        const missing = this.templateMissingHaHosts(templateId);
        return missing.length ? { type: 'ha_stack', hostIds: missing.map((item) => item.id) } : { type: 'review_host' };
      }
      if (key === 'tools' || key === 'agents') {
        const missing = this.templateMissingHaHosts(templateId);
        return missing.length ? { type: 'ha_stack', hostIds: missing.map((item) => item.id) } : { type: 'review_host' };
      }
      if (key === 'time') {
        const missing = hosts.filter((_, index) => !checks[index]?.checks?.time_synchronized);
        return missing.length ? { type: 'time_sync', hostIds: missing.map((item) => item.id), action: 'enable_time_sync' } : { type: 'review_host' };
      }
      if (key === 'pool') {
        const host = hosts.find((_, index) => !checks[index]?.checks?.libvirt_pools?.length);
        return host ? { type: 'storage_pool', hostId: host.id } : { type: 'review_host' };
      }
      if (key === 'app') {
        const serviceName = templateId === 'web' ? 'apache2' : 'nfsserver';
        const missing = hosts.filter((_, index) => !checks[index]?.checks?.workload_services?.[serviceName]);
        return missing.length ? { type: 'workload_package', hostIds: missing.map((item) => item.id), action: templateId === 'web' ? 'install_web_package' : 'install_nfs_package' } : { type: 'review_host' };
      }
      return { type: 'review_host' };
    },
    async runTemplateRequirementAction(templateId: string, key: string) {
      const remedy = this.templateRequirementRemedy(templateId, key);
      this.templateActionTemplateId = templateId;
      this.templateResolveError = '';
      if (remedy.type === 'select_hosts') { document.getElementById('template-host-selection-title')?.scrollIntoView({ behavior: 'smooth', block: 'center' }); return; }
      if (remedy.type === 'preflight') { await this.runPreflight(this.templateHostIds); return; }
      if (remedy.type === 'host_connectivity') { this.goToHosts(); return; }
      if (remedy.type === 'subscription') { const host = this.hosts.find((item) => item.id === remedy.hostId); if (host) this.goToSubscriptions(host); return; }
      if (remedy.type === 'ha_stack') { await this.installMissingHaToolsForTemplate(templateId); return; }
      if (remedy.type === 'storage_pool') { this.$router.push({ name: 'kvm-c-cluster-cloud-native', query: { hostId: remedy.hostId, tab: 'storage' } }); return; }
      if (remedy.type === 'time_sync' || remedy.type === 'workload_package') await this.resolveTemplateAction(remedy.action || '', remedy.hostIds || []);
      else this.activeSection = 'overview';
    },
    templateRequiredAgents(templateId: string): string[] {
      const byTemplate: Record<string, string[]> = { service: ['heartbeat:IPaddr2'], vm: ['heartbeat:VirtualDomain'], web: ['heartbeat:apache'], nfs: ['heartbeat:Filesystem','heartbeat:exportfs','heartbeat:nfsserver','heartbeat:IPaddr2'] };
      return byTemplate[templateId] || [];
    },
    templateMissingHaHosts(templateId: string): Host[] {
      const required = this.templateRequiredAgents(templateId);
      return this.selectedTemplateHosts.filter((host) => {
        if (!host.ha?.ha_active) return false;
        const check = this.preflightResults.find((item) => item.host_id === host.id)?.checks;
        const commandsMissing = !this.haToolsInstalled(host) || (check && (!check.tools?.crm || !check.tools?.crm_mon));
        const agentsMissing = Boolean(check && required.some((agent) => !(check.resource_agents || []).includes(agent)));
        return Boolean(commandsMissing || agentsMissing);
      });
    },
    templateMissingHaAddonHosts(_templateId: string): Host[] {
      return this.selectedTemplateHosts.filter((host) => !host.ha?.ha_active && Boolean(host.ha?.ha_available));
    },
    templateHostActionResults(templateId: string): StackInstallResult[] {
      if (this.templateActionTemplateId !== templateId) return [];
      const stackResults = this.selectedTemplateHosts.map((host) => this.haToolResults[host.id]).filter(Boolean);
      return [...stackResults, ...this.templateResolveResults];
    },
    templateRemediation(templateId: string): { type: string; hostId?: string; hostIds?: string[]; action?: string } | null {
      if (this.selectedTemplateHosts.length < 2) return { type: 'select_hosts' };
      const results = this.selectedTemplateHosts.map((host) => this.preflightResults.find((item) => item.host_id === host.id));
      const failedCheck = results.find((item) => item?.status === 'error');
      if (failedCheck) return { type: 'host_connectivity', hostId: failedCheck.host_id };
      if (!results.length || results.some((item) => item?.status !== 'checked' || !item.checks)) return { type: 'preflight' };
      const haMissing = this.selectedTemplateHosts.find((host, index) => !results[index]?.checks?.ha_active);
      if (haMissing) return { type: 'subscription', hostId: haMissing.id };
      const stackMissing = this.templateMissingHaHosts(templateId);
      if (stackMissing.length) return { type: 'ha_stack', hostIds: stackMissing.map((host) => host.id) };
      const timeMissing = this.selectedTemplateHosts.filter((_, index) => !results[index]?.checks?.time_synchronized);
      if (timeMissing.length) return { type: 'time_sync', hostIds: timeMissing.map((host) => host.id) };
      if (templateId === 'web' || templateId === 'nfs') {
        const serviceName = templateId === 'web' ? 'apache2' : 'nfsserver';
        const missing = this.selectedTemplateHosts.filter((_, index) => !results[index]?.checks?.workload_services?.[serviceName]);
        if (missing.length) return { type: 'workload_package', hostIds: missing.map((host) => host.id), action: templateId === 'web' ? 'install_web_package' : 'install_nfs_package' };
      }
      if (templateId === 'vm') {
        const missingPoolHost = this.selectedTemplateHosts.find((_, index) => !results[index]?.checks?.libvirt_pools?.length);
        if (missingPoolHost) return { type: 'storage_pool', hostId: missingPoolHost.id };
      }
      if (this.templateEvaluation(templateId).fit !== 'candidate') return { type: 'review_host' };
      return null;
    },
    templateRemediationText(templateId: string): string {
      const remedy = this.templateRemediation(templateId);
      return this.t(`clusters.templateAction_${remedy?.type || 'none'}`);
    },
    templateRemediationLabel(templateId: string): string {
      const remedy = this.templateRemediation(templateId);
      return this.t(`clusters.templateActionButton_${remedy?.type || 'none'}`, { count: remedy?.hostIds?.length || 0 });
    },
    templateRemediationDisabled(templateId: string): boolean {
      const type = this.templateRemediation(templateId)?.type;
      if (type === 'preflight') return this.preflightLoading;
      if (type === 'ha_stack') return !this.canManageCluster || this.haToolsBatchLoading || this.haToolBusyHostIds.length > 0;
      if (type === 'time_sync' || type === 'workload_package') return !this.canManageCluster || this.templateResolveLoading;
      return false;
    },
    templateRemediationLoading(templateId: string): boolean {
      const type = this.templateRemediation(templateId)?.type;
      return this.templateResolveLoading && (type === 'time_sync' || type === 'workload_package') || this.haToolsBatchLoading && type === 'ha_stack';
    },
    async runTemplateRemediation(templateId: string) {
      const remedy = this.templateRemediation(templateId);
      if (!remedy) return;
      this.templateActionTemplateId = templateId;
      this.templateResolveError = '';
      if (remedy.type === 'select_hosts') { document.getElementById('template-host-selection-title')?.scrollIntoView({ behavior: 'smooth', block: 'center' }); return; }
      if (remedy.type === 'preflight') { await this.runPreflight(this.templateHostIds); return; }
      if (remedy.type === 'subscription') { const host = this.hosts.find((item) => item.id === remedy.hostId); if (host) this.goToSubscriptions(host); return; }
      if (remedy.type === 'ha_stack') { await this.installMissingHaToolsForTemplate(templateId); return; }
      if (remedy.type === 'storage_pool') { this.$router.push({ name: 'kvm-c-cluster-cloud-native', query: { hostId: remedy.hostId, tab: 'storage' } }); return; }
      if (remedy.type === 'review_host') { this.activeSection = 'overview'; return; }
      if (remedy.type === 'time_sync' || remedy.type === 'workload_package') await this.resolveTemplateAction(remedy.action || (remedy.type === 'time_sync' ? 'enable_time_sync' : ''), remedy.hostIds || []);
    },
    async resolveTemplateAction(action: string, hostIds: string[]) {
      if (!this.canManageCluster || !hostIds.length || this.templateResolveLoading) return;
      this.templateResolveLoading = true; this.templateResolveError = ''; this.templateResolveResults = [];
      try {
        const response = await fetch(`${apiBase}/clusters/templates/resolve-prerequisite`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action, host_ids: hostIds }) });
        const body = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`);
        const job = await this.trackOperationJob(body, (progress) => { this.templateResolveResults = progress as TemplateResolveResult[]; });
        this.templateResolveResults = job.results as TemplateResolveResult[];
        await this.fetchReadiness(); await this.runPreflight(this.templateHostIds);
      } catch (error) { this.templateResolveError = (error as Error).message; }
      finally { this.templateResolveLoading = false; }
    },
    async installMissingHaToolsForTemplate(templateId: string) {
      const hosts = this.templateMissingHaHosts(templateId);
      if (!this.canManageCluster || !hosts.length || this.haToolsBatchLoading || this.haToolBusyHostIds.length) return;
      const ids = hosts.map((host) => host.id);
      this.haToolsBatchLoading = true; this.haToolBusyHostIds = ids;
      for (const host of hosts) this.haToolResults[host.id] = { host_id: host.id, host_name: host.hostname || host.name, status: 'installing' };
      try {
        const response = await fetch(`${apiBase}/clusters/install-stack`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ host_ids: ids }) });
        const body = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`);
        const job = await this.trackOperationJob(body, (progress) => { for (const item of progress as StackInstallResult[]) this.haToolResults[item.host_id] = item; });
        const results = job.results as StackInstallResult[];
        const byHost = new Map(results.map((item) => [item.host_id, item]));
        for (const host of hosts) this.haToolResults[host.id] = byHost.get(host.id) || { host_id: host.id, host_name: host.hostname || host.name, status: 'error', error: this.t('clusters.haToolsMissingResult') };
        await this.fetchReadiness(); await this.runPreflight(this.templateHostIds);
      } catch (error) {
        for (const host of hosts) this.haToolResults[host.id] = { host_id: host.id, host_name: host.hostname || host.name, status: 'error', error: (error as Error).message };
      } finally { this.haToolBusyHostIds = this.haToolBusyHostIds.filter((id) => !ids.includes(id)); this.haToolsBatchLoading = false; }
    },
    async trackOperationJob(initial: OperationJob, onProgress: (results: OperationJob['results']) => void): Promise<OperationJob> {
      if (!initial?.job_id) throw new Error(this.t('clusters.operationJobMissing'));
      let current = initial;
      onProgress(current.results || []);
      for (let attempt = 0; attempt < 1800; attempt += 1) {
        if (['succeeded', 'partial', 'failed'].includes(current.status)) return current;
        await new Promise((resolve) => window.setTimeout(resolve, 1000));
        const response = await fetch(`${apiBase}/operations/${encodeURIComponent(initial.job_id)}`, { credentials: 'include', cache: 'no-store' });
        const body = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`);
        current = body as OperationJob;
        onProgress(current.results || []);
      }
      throw new Error(this.t('clusters.operationJobTimeout'));
    },
    templateMinimumCapacity(): string { const hosts = this.selectedTemplateHosts; const cpus = hosts.map((host) => host.cpu_count || 0); const memories = hosts.map((host) => host.memory_total_bytes || 0); if (cpus.length < 2 || cpus.some((count) => count <= 0) || memories.some((bytes) => bytes <= 0)) return this.t('clusters.templateVmCapacityUnknown'); return this.t('clusters.templateVmCapacity', { cpu: Math.min(...cpus), memory: (Math.min(...memories) / 1024 ** 3).toFixed(1) }); },
    templatePreviewItems(templateId: string): string[] { return ['resources','ordering','dependencies'].map((item) => this.t(`clusters.template_${templateId}_${item}`)); },
    haToolsInstalled(host: Host): boolean { return Boolean(host.ha?.commands?.crm && host.ha?.commands?.crm_mon); },
    async installHaTools(host: Host) { if (!this.canManageCluster || !host.ha?.ha_active || this.haToolBusyHostIds.includes(host.id)) return; this.haToolBusyHostIds = [...this.haToolBusyHostIds, host.id]; this.haToolResults[host.id] = { host_id: host.id, host_name: host.hostname || host.name, status: 'queued' }; try { const response = await fetch(`${apiBase}/clusters/install-stack`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ host_ids: [host.id] }) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); const job = await this.trackOperationJob(body, (progress) => { const result = (progress as StackInstallResult[])[0]; if (result) this.haToolResults[host.id] = result; }); this.haToolResults[host.id] = (job.results[0] as StackInstallResult) || { host_id: host.id, host_name: host.hostname || host.name, status: 'error', error: this.t('clusters.haToolsInstallFailed') }; await this.fetchReadiness(); } catch (error) { this.haToolResults[host.id] = { host_id: host.id, host_name: host.hostname || host.name, status: 'error', error: (error as Error).message }; } finally { this.haToolBusyHostIds = this.haToolBusyHostIds.filter((id) => id !== host.id); } },
    async installHaToolsForEligibleHosts() { const hosts = this.haToolsEligibleHosts; if (!this.canManageCluster || !hosts.length || this.haToolBusyHostIds.length) return; const hostIds = hosts.map((host) => host.id); this.haToolsBatchLoading = true; this.haToolBusyHostIds = hostIds; for (const host of hosts) this.haToolResults[host.id] = { host_id: host.id, host_name: host.hostname || host.name, status: 'queued' }; try { const response = await fetch(`${apiBase}/clusters/install-stack`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ host_ids: hostIds }) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); await this.trackOperationJob(body, (progress) => { for (const item of progress as StackInstallResult[]) this.haToolResults[item.host_id] = item; }); try { await this.fetchReadiness(); } catch (error) { this.error = `${this.t('clusters.loadError')}: ${(error as Error).message}`; } } catch (error) { for (const host of hosts) this.haToolResults[host.id] = { host_id: host.id, host_name: host.hostname || host.name, status: 'error', error: (error as Error).message }; } finally { this.haToolBusyHostIds = this.haToolBusyHostIds.filter((id) => !hostIds.includes(id)); this.haToolsBatchLoading = false; } },
    async installHaStack() { const hostIds = this.haStackMissingHosts.map((host) => host.id); if (!hostIds.length) return; this.stackInstallLoading = true; this.stackInstallResults = []; this.preflightError = ''; try { const response = await fetch(`${apiBase}/clusters/install-stack`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ host_ids: hostIds }) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.detail || `API request failed (${response.status})`); const job = await this.trackOperationJob(body, (progress) => { this.stackInstallResults = progress as StackInstallResult[]; }); this.stackInstallResults = job.results as StackInstallResult[]; this.pendingInstallStack = false; await this.fetchReadiness(); await this.runPreflight(); } catch (error) { this.preflightError = (error as Error).message; } finally { this.stackInstallLoading = false; } },
    async refreshStale() { if (this.refreshingStale || !this.hosts.length) return; this.refreshingStale = true; try { await this.fetchReadiness(); } catch { /* Keep the latest host status visible during transient API failures. */ } finally { this.refreshingStale = false; } },
    goToHosts() { this.$router.push({ name: 'kvm-hosts' }); },
    goToSubscriptions(host: Host) { this.$router.push({ name: 'kvm-c-cluster-cloud-native', query: { hostId: host.id, tab: 'subscriptions' } }); },
    openManagedKvmClusters() { this.$router.push({ name: 'kvm-c-managed-clusters', params: { cluster: '_' } }); },
    operationStatusText(status: string) { const key: Record<string,string> = { queued: 'operationQueued', running: 'operationRunning', resolved: 'operationResolved', installed: 'operationInstalled', completed: 'operationResolved', error: 'operationFailed', failed: 'operationFailed' }; return this.t(`clusters.${key[status] || 'operationRunning'}`); },
    sectionIcon(section: string) { return ({ clusters: '◇', templates: '▦', overview: '◉', plan: '⌁', nodes: '▤', resources: '◆', constraints: '⌘', activity: '≋', fencing: '⬡' } as Record<string,string>)[section] || '•'; },
    statusLabel(status: string) { return this.t(`hosts.${status === 'ready' ? 'ready' : status === 'unreachable' ? 'unreachable' : 'unknown'}`); },
    haLabel(host: Host) { const ha = host.ha; if (ha?.inspection_error || ha?.extension_error || !ha?.suseconnect_available) return this.t('clusters.haUnknown'); if (ha.ha_active) return this.t('clusters.haEnabled'); if (ha.ha_available) return this.t('clusters.haAvailable'); return this.t('clusters.haUnavailable'); },
    haClass(host: Host) { const ha = host.ha; return ha?.inspection_error || ha?.extension_error || !ha?.suseconnect_available ? 'unknown' : ha.ha_active ? 'ready' : ha.ha_available ? 'warning-state' : 'unreachable'; },
    serviceLabel(host: Host, name: string) { const state = host.ha?.services?.[name]; return this.t(state === 'active' ? 'clusters.active' : state === 'inactive' || state === 'failed' ? 'clusters.inactive' : 'clusters.notInstalled'); },
    serviceClass(host: Host, name: string) { const state = host.ha?.services?.[name]; return state === 'active' ? 'service-active' : state === 'inactive' || state === 'failed' ? 'service-inactive' : 'service-missing'; },
    clusterStateKey(host: Host) { const ha = host.ha; if (ha?.inspection_error) return 'clusters.haUnknown'; if (!ha?.ha_active) return 'clusters.notApplicable'; if (ha.cluster_detected) return 'clusters.clusterDetected'; if (!ha.commands?.crm || !ha.commands?.crm_mon) return 'clusters.haStackMissing'; if (ha.services?.pacemaker !== 'active' || ha.services?.corosync !== 'active') return 'clusters.haStackStopped'; return 'clusters.clusterNotInitialized'; },
    clusterStateClass(host: Host) { const key = this.clusterStateKey(host); return key === 'clusters.clusterDetected' ? 'ready' : key === 'clusters.haUnknown' ? 'unknown' : key === 'clusters.clusterNotInitialized' ? 'warning-state' : 'unreachable'; },
    memoryLabel(bytes?: number) { if (!bytes) return '—'; const gib = bytes / 1024 ** 3; return `${gib.toFixed(gib >= 10 ? 0 : 1)} GiB`; },
    dateLabel(value?: string) { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleString(); },
  },
});
</script>

